    fn get(&mut self, receiver: &ObjectRef, name: &str) -> Result<Option<Value>, String> {
        if name.eq_ignore_ascii_case("Path") {
            let application = self.application.borrow();
            if let Some(owner) = application.native_owner(receiver) {
                if application.hosts[&owner].is_workbook(receiver) && application.save_operations.values().any(|operation|
                    operation.arguments.as_ref().is_some_and(|arguments| arguments.owner==owner && arguments.path_unavailable)) {
                    let description = match application.hosts[&owner].error_language {
                        ErrorLanguage::Japanese => "'Path' メソッドは失敗しました: '_Workbook' オブジェクト",
                        ErrorLanguage::English => "Method 'Path' of object '_Workbook' failed",
                    };
                    return Err(host_error_described(1004, description));
                }
            }
        }
        if let Some(result) = self.workbooks_call(Some(receiver), name, &[], &[], None) { return result; }
        let mut result = self.write(Some(receiver), name, false, |host, receiver| {
            host.get(receiver.expect("native receiver"), name)
        });
        self.canonical_result(&mut result);
        result
    }
