/// Opaque leases own the original dispatch reference, including its interface.
/// Serialized handle/kind fields describe an object; they never reconstruct it.
struct ExternalReferences {
    namespace: String,
    next: u64,
    values: BTreeMap<String, ObjectRef>,
}

impl Default for ExternalReferences {
    fn default() -> Self {
        static NEXT_SESSION: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(1);
        let serial = NEXT_SESSION.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        #[cfg(target_arch = "wasm32")]
        let namespace = format!("{:x}-{:x}-{:x}-{serial:x}", js_sys::Date::now().to_bits(),
            js_sys::Math::random().to_bits(), js_sys::Math::random().to_bits());
        #[cfg(not(target_arch = "wasm32"))]
        let namespace = format!("native-{serial:x}");
        Self { namespace, next: 0, values: BTreeMap::new() }
    }
}

impl ExternalReferences {
    fn retain(&mut self, value: &mut OutputValue) {
        match value {
            OutputValue::Object { object, reference, .. } => {
                self.next = self.next.checked_add(1).expect("VBA reference sequence exhausted");
                let token = format!("{}-{:x}", self.namespace, self.next);
                self.values.insert(token.clone(), object.clone());
                *reference = Some(token);
            }
            OutputValue::Array { values, .. } => {
                for value in values { self.retain(value); }
            }
            OutputValue::Record { fields, .. } => {
                for (_, value) in fields { self.retain(value); }
            }
            _ => {}
        }
    }

    fn tokens_in_release_order(&self) -> Vec<String> {
        let mut tokens: Vec<_> = self.values.keys().cloned().collect();
        tokens.sort_by_cached_key(|token| std::cmp::Reverse(
            u64::from_str_radix(token.rsplit('-').next().expect("owned token"), 16).expect("owned token sequence")));
        tokens
    }

    fn snapshot(&self) -> VbaReferenceState {
        VbaReferenceState { owner: self.namespace.clone(), tokens: self.values.keys().cloned().collect() }
    }

    fn reset_project(&mut self) {
        // Host objects retain their identities when project storage resets.
        self.values.retain(|_, object| object.life.is_none() || object.is_native_stream());
    }
}

#[derive(Serialize)]
struct VbaReferenceState {
    owner: String,
    tokens: Vec<String>,
}

struct VbaInvocation<'a, A> {
    procedure: Option<&'a str>,
    args: A,
    action: Option<ExternalObjectAction>,
}

impl<'a, A> VbaInvocation<'a, A> {
    fn new(procedure: Option<&'a str>, args: A) -> Self { Self { procedure, args, action: None } }
}

enum ExternalObjectAction {
    Invoke { reference: String, member: String, kind: i64 },
    Release { references: Vec<String> },
    SaveWorkbook { copy_name: Option<String> },
    CompileProject,
}

fn value_owns_project_reference(value: &Value) -> bool {
    match value {
        Value::Object(object) => object.life.is_some() && !object.is_native_stream(),
        Value::Array(array) => array.values.iter().any(value_owns_project_reference),
        Value::Record(record) => record.fields.iter().any(|(_, value)| value_owns_project_reference(value)),
        _ => false,
    }
}


// Parsed code and proxy hosts live only for one invocation. The arenas own
// destructors as well as allocations; ApplicationStorage owns the surviving
// object graph and does not borrow either arena.
type ApplicationParsedCode = (oxivba_core::ast::Module, Vec<(String, oxivba_core::ast::Module)>);

struct ApplicationCode {
    source: String,
    project_name: String,
    documents: Vec<VbaDocumentModule>,
}

fn application_runtime_error(message: impl Into<String>) -> oxivba_core::RuntimeError {
    oxivba_core::RuntimeError {
        kind: oxivba_core::RuntimeErrorKind::Host,
        message: message.into(),
        line: None,
        vba_number: None,
        vba_source: None,
        vba_help_file: None,
        vba_help_context: None,
        vba_default_description: false,
    }
}

struct ApplicationExecutionContext {
    environment: ErrorEnvironment,
    current_time: f64,
    random_seed: u64,
    constants: std::sync::Arc<BTreeMap<String, i64>>,
}

fn loaded_application_runtime<'code>(
    owner: u64,
    application: &std::rc::Rc<std::cell::RefCell<WorkbookApplication<'static>>>,
    code: &'code typed_arena::Arena<ApplicationParsedCode>,
    hosts: &'code typed_arena::Arena<ApplicationHost<'static>>,
    context: &ApplicationExecutionContext,
) -> Result<Runtime<'code>, oxivba_core::RuntimeError> {
    let (parsed, project_name, references, bindings) = {
        let mut books = application.borrow_mut();
        let definition = books.code.get(&owner)
            .ok_or_else(|| application_runtime_error("No source definition for the opened workbook"))?;
        let parsed = oxivba_core::parse_project(&definition.source)
            .map_err(|error| application_runtime_error(error.to_string()))?;
        let project_name = definition.project_name.clone();
        let mut references = builtin_compilation_references().clone();
        references.document_modules = definition.documents.iter().filter(|document| !document.host_only)
            .map(|document| (document.name.clone(), document.base_type.clone())).collect();
        let host = books.hosts.get_mut(&owner)
            .ok_or_else(|| application_runtime_error("The opened workbook is no longer registered"))?;
        host.user_functions.borrow_mut().fixed_reference_functions =
            fixed_reference_functions(&parsed.0, &parsed.1);
        let bindings = host.document_objects.iter()
            .map(|(name, object)| (name.clone(), object.clone())).collect();
        (parsed, project_name, std::sync::Arc::new(references), bindings)
    };
    let (module, classes) = code.alloc(parsed);
    let host = hosts.alloc(ApplicationHost {
        application: application.clone(),
        code_owner: owner,
    });
    let mut runtime = Runtime::new(module)
        .with_classes(classes)
        .with_host(host)
        .with_error_environment(context.environment.clone())
        .with_project_name(project_name)
        .with_current_time(context.current_time)
        .with_random_seed(context.random_seed)
        .with_reference_constants(context.constants.clone());
    runtime.set_application_project_identity(owner)?;
    runtime.prepare_worksheet_functions();
    runtime.with_document_objects(bindings, references)
}

struct ApplicationSessionState {
    // The invoking host is retained separately in ProjectSessionState so the
    // editor can supply its current IR without replacing any other workbook.
    application: WorkbookApplication<'static>,
    runtime: oxivba_core::ApplicationStorage,
}

struct ProjectSessionState {
    source: String,
    project_name: String,
    // Only an explicit workbook selection binds the default for later calls.
    // An invocation's projectName override must not become the next default.
    selected_project_name: Option<String>,
    runtime: Option<oxivba_core::ProjectState>,
    application: Option<ApplicationSessionState>,
    host: WorkbookHostState,
    workbook: Vec<u8>,
    documents: Vec<VbaDocumentModule>,
    external_references: ExternalReferences,
}

fn invocation_project_name(session: Option<&ProjectSessionState>, requested: Option<&str>) -> String {
    requested.or_else(|| session.and_then(|state| state.selected_project_name.as_deref()))
        .unwrap_or("VBAProject").to_string()
}

#[derive(Serialize)]
struct WorkbookSelection {
    package_bytes: Option<Vec<u8>>,
    selected: OpenWorkbookOutput,
    other_workbooks: Vec<OpenWorkbookOutput>,
    application_state: VbaApplicationState,
    file_system_state: file_io::FileSystemState,
}

fn selection_snapshot(state: &ProjectSessionState) -> Result<WorkbookSelection, String> {
    let selected = OpenWorkbookOutput {
        identity: state.host.objects.owner.to_string(),
        name: state.host.file_name.clone().unwrap_or_else(|| "Book1".into()),
        full_name: state.host.file_io.full_name.clone(),
        read_only: state.host.file_io.read_only,
        saved: state.host.saved,
        active_sheet: state.host.active_sheet,
        source: state.source.clone(),
        project_name: state.project_name.clone(),
        document_modules: state.documents.clone(),
        workbook: serde_json::from_slice(&state.workbook).map_err(|error| error.to_string())?,
    };
    let other_workbooks = state.application.as_ref().map(|application| {
        application.application.hosts.iter().filter(|(owner,_)|!application.application.closed.contains(owner)).map(|(owner, host)| {
            let code = &application.application.code[owner];
            OpenWorkbookOutput {
                identity: owner.to_string(),
                name: host.file_name.clone().unwrap_or_else(|| "Book1".into()),
                full_name: host.file_io.full_name.clone(),
                read_only: host.file_io.read_only,
                saved: host.saved,
                active_sheet: host.active_sheet,
                source: code.source.clone(),
                project_name: code.project_name.clone(),
                document_modules: code.documents.clone(),
                workbook: (*host.workbook).clone(),
            }
        }).collect()
    }).unwrap_or_default();
    let host = &state.host;
    let application_state = VbaApplicationState {
        calculation: host.calculation,
        calculate_before_save: host.app_settings.get("calculatebeforesave") == Some(&Value::Boolean(true)),
        screen_updating: host.screen_updating, enable_events: host.enable_events,
        display_alerts: host.display_alerts, status_bar: host.status_bar.clone(),
        cursor: host.cursor, interactive: host.interactive,
        directory_state: Some(VbaDirectoryState::capture(&host.file_io.files)),
        new_workbook_font: (host.application_font!=default_application_font()).then(||host.application_font.clone()),
        standard_font_startup: None,
        standard_font_preference_present: (host.app_settings.get("_standard_font_preference_missing") == Some(&Value::Boolean(true))).then_some(false),
        pending_standard_font_profile_utf16: host.app_settings.get("_standard_font_pending_profile")
            .and_then(|value| value.string_units()).map(|units| units.into_owned()),
        caption_suffix_utf16: host.app_settings.get("caption").and_then(|value|value.string_units()).map(|units|units.into_owned()),
        caption_without_window: (host.app_settings.get("_caption_without_window") == Some(&Value::Boolean(true))).then_some(true),
        caption_window: VbaCaptionWindow::capture(&host.app_settings),
    };
    Ok(WorkbookSelection { package_bytes: host.file_io.package.clone(), selected, other_workbooks, application_state,
        file_system_state: host.file_io.snapshot() })
}

/// Keep editor cell/structure changes in the actual host before its view is
/// detached. This does not run source code or turn activation into a Save.
#[cfg(test)]
fn select_session_workbook_with_edits(
    session: &mut Option<ProjectSessionState>, identity: &str,
    workbook: Workbook, active_sheet: usize,
) -> Result<WorkbookSelection, String> {
    select_session_workbook_with_revision(session, identity, workbook, active_sheet, None)
}

fn select_session_workbook_with_revision(
    session: &mut Option<ProjectSessionState>, identity: &str,
    workbook: Workbook, active_sheet: usize, edit_revision: Option<u64>,
) -> Result<WorkbookSelection, String> {
    let owner: u64 = identity.parse().map_err(|_| "invalid workbook identity".to_string())?;
    if owner.to_string() != identity { return Err("invalid workbook identity".into()); }
    let previous = session.as_ref().ok_or("no loaded VBA project")?;
    if previous.application.as_ref().is_some_and(|state|state.application.closed.contains(&owner)) {
        return Err("workbook is not open in this session".into());
    }
    if previous.application.as_ref().is_some_and(|state|state.application.closed.contains(&previous.host.objects.owner)) {
        return select_session_workbook(session,identity);
    }
    if owner != previous.host.objects.owner && !previous.application.as_ref()
        .is_some_and(|application| application.application.hosts.contains_key(&owner)
            && application.application.code.contains_key(&owner)) {
        return Err("workbook is not open in this session".into());
    }
    if active_sheet >= workbook.sheets.len() { return Err("active sheet is outside this workbook".into()); }
    let old_workbook: Workbook = serde_json::from_slice(&previous.workbook).map_err(|error| error.to_string())?;
    let incoming = serde_json::to_vec(&workbook).map_err(|error| error.to_string())?;
    let mut previous = session.take().expect("validated project");
    let mut host = WorkbookHost::resume_storage(WorkbookStorage::Owned(Box::new(workbook)), previous.host);
    remap_workbook_host(&mut host, &old_workbook, &previous.documents, false);
    if previous.workbook != incoming { host.saved = false; }
    if let Some(revision) = edit_revision {
        if host.file_io.edit_revision.unwrap_or(0) != revision { host.saved = false; }
        host.file_io.edit_revision = Some(revision);
    }
    host.activate_sheet(active_sheet);
    let (_, host) = host.into_parts();
    previous.host = host;
    previous.workbook = incoming;
    *session = Some(previous);
    select_session_workbook(session, identity)
}

fn select_session_workbook(session: &mut Option<ProjectSessionState>, identity: &str) -> Result<WorkbookSelection, String> {
    let owner: u64 = identity.parse().map_err(|_| "invalid workbook identity".to_string())?;
    if identity != owner.to_string() { return Err("invalid workbook identity".into()); }
    let previous = session.as_ref().ok_or("no loaded VBA project")?;
    let old_owner = previous.host.objects.owner;
    if previous.application.as_ref().is_some_and(|state|state.application.closed.contains(&owner)) {
        return Err("workbook is not open in this session".into());
    }
    if old_owner == owner {
        let state = session.as_mut().expect("loaded project");
        state.selected_project_name = Some(state.project_name.clone());
        if let Some(application) = state.application.as_mut() {
            application.application.activate(owner);
        }
        return selection_snapshot(state);
    }
    let application = previous.application.as_ref().ok_or("workbook is not open in this session")?;
    let selected = application.application.hosts.get(&owner).ok_or("workbook is not open in this session")?;
    let definition = application.application.code.get(&owner).ok_or("missing workbook source")?;
    let source = definition.source.clone();
    let project_name = definition.project_name.clone();
    let documents = definition.documents.clone();
    let workbook = serde_json::to_vec(&*selected.workbook).map_err(|error| error.to_string())?;
    let old_workbook = serde_json::from_slice(&previous.workbook).map_err(|error| error.to_string())?;
    // All validation precedes the move. The actual native handle table,
    // application object heap and every project's code storage stay owned.
    let previous = session.take().expect("validated project");
    let mut application = previous.application.expect("validated application");
    let old_host = WorkbookHost::resume_storage(WorkbookStorage::Owned(Box::new(old_workbook)), previous.host);
    application.application.code.insert(old_owner, ApplicationCode {
        source: previous.source, project_name: previous.project_name, documents: previous.documents,
    });
    assert!(application.application.insert(old_host).is_ok(), "detached root has a unique native owner");
    application.application.ensure_application_owner(owner);
    application.application.activate(owner);
    let mut selected = application.application.hosts.remove(&owner).expect("validated selected workbook");
    selected.file_io.swap_application_files(&mut application.application.hosts
        .get_mut(&old_owner).expect("previous root").file_io);
    selected.file_io.files.select_project(owner);
    let (_, host) = selected.into_parts();
    *session = Some(ProjectSessionState {
        selected_project_name: Some(project_name.clone()),
        source, project_name, documents, workbook, host, runtime: None,
        application: Some(application), external_references: previous.external_references,
    });
    selection_snapshot(session.as_ref().expect("selected project"))
}

// A single-call entry may return live objects. Keep its actual project/host
// graph until the consumer adopts it; serialized handles cannot recreate it.
std::thread_local! {
    static RETURNED_VBA_PROJECTS: std::cell::RefCell<BTreeMap<String, ProjectSessionState>>
        = const { std::cell::RefCell::new(BTreeMap::new()) };
}

fn retain_returned_project(state: Option<ProjectSessionState>) {
    if let Some(state) = state {
        if !state.external_references.values.is_empty() {
            RETURNED_VBA_PROJECTS.with(|projects| {
                projects.borrow_mut().insert(state.external_references.namespace.clone(), state);
            });
        }
    }
}

fn take_returned_project(reference: &str) -> Result<ProjectSessionState, String> {
    let missing = || "invalid VBA object reference: released, stale, or foreign reference (result already adopted)".to_string();
    let (owner, _) = reference.rsplit_once('-').ok_or_else(missing)?;
    RETURNED_VBA_PROJECTS.with(|projects| {
        let mut projects = projects.borrow_mut();
        let valid = projects.get(owner).is_some_and(|state| state.external_references.values.contains_key(reference));
        if !valid { return Err(missing()); }
        Ok(projects.remove(owner).expect("validated returned project"))
    })
}

#[derive(Default,Deserialize)]
#[serde(default,rename_all="camelCase",deny_unknown_fields)]
struct VbaCompilationOptions {
    project_name: Option<String>,
    error_language: Option<String>,
    current_year: Option<i64>,
    reference_types: Vec<VbaCompilationType>,
    reference_symbols: Vec<VbaCompilationSymbol>,
    reference_namespaces: Vec<String>,
    document_modules: Vec<VbaDocumentModule>,
}

#[derive(Default,Deserialize,Serialize,Debug,Clone,PartialEq,Eq)]
#[serde(rename_all="camelCase",deny_unknown_fields)]
pub(crate) struct VbaDocumentModule {
    pub name:String, pub base_type:String,
    #[serde(default,skip_serializing_if="Option::is_none")]
    pub sheet_index:Option<usize>,
    #[serde(default,skip_serializing_if="Option::is_none")]
    pub code_name:Option<String>,
    // Imported document classes can exist without an attached native object.
    // Explicit host bindings retain their historical default of being attached.
    #[serde(default,skip_serializing_if="document_flag_is_false")]
    pub unbound:bool,
    // Native object metadata without a PROJECT document declaration.
    #[serde(default,skip_serializing_if="document_flag_is_false")]
    pub host_only:bool,
}

fn document_flag_is_false(flag:&bool)->bool { !*flag }

#[derive(Deserialize)]
#[serde(rename_all="camelCase",deny_unknown_fields)]
struct VbaCompilationType {name:String,#[serde(default)] numeric:bool}

#[derive(Deserialize)]
#[serde(rename_all="camelCase",deny_unknown_fields)]
struct VbaCompilationSymbol {name:String,#[serde(default)] value:Option<i64>}

#[derive(Debug,Serialize)]
struct VbaCompilationOutcome {
    compiled: bool,
    #[serde(skip_serializing_if="Option::is_none")]
    error: Option<VbaCompilationDiagnostic>,
}

#[derive(Debug,Serialize)]
struct VbaCompilationDiagnostic {
    kind: &'static str,
    message: String,
    module: String,
    line: u32,
    #[serde(skip_serializing_if="Option::is_none")]
    procedure: Option<String>,
}

/// The stateful operation is distinct from the read-only syntax checker.
#[derive(Debug, Serialize)]
struct ProjectCompilation {
    compiled: bool,
    #[serde(skip_serializing_if="Option::is_none")]
    error: Option<VbaCompilationDiagnostic>,
    performed: bool,
}

pub(crate) fn builtin_compilation_references() -> &'static oxivba_core::CompileReferences {
    static REFERENCES:std::sync::OnceLock<oxivba_core::CompileReferences>=std::sync::OnceLock::new();
    REFERENCES.get_or_init(|| {
        let mut references=oxivba_core::CompileReferences::default();
        references.library=std::sync::Arc::new(oxivba_core::CompileReferenceLibrary::from_tsv(include_str!("vba_reference_signatures.tsv")).expect("reference signatures"));
        for line in include_str!("vba_builtin_references.tsv").lines().filter(|line|!line.starts_with('#') && !line.is_empty()) {
            let fields:Vec<_>=line.split('\t').collect();
            match fields[0] {
                "N"=>references.namespaces.push(fields[1].to_string()),
                "T"=>references.types.push((fields[1].to_string(),fields[2]=="1")),
                "S"=>references.symbols.push((fields[1].to_string(),if fields[2]=="-" {None}else{Some(fields[2].parse().expect("reference constant"))})),
                _=>unreachable!("reference record"),
            }
        }
        references.symbols.extend(VBA_HOST_CONSTANTS.iter()
            .map(|(name, value)| (name.to_string(), Some(*value))));
        references
    })
}

fn compilation_outcome(source:&str,language:ErrorLanguage,references:&oxivba_core::CompileReferences) -> VbaCompilationOutcome {
    match oxivba_core::compile_project_with_references(source,references) {
        Ok(())=>VbaCompilationOutcome {compiled:true,error:None},
        Err(failure)=> {
            let prefix=match language {ErrorLanguage::English=>"Compile error",ErrorLanguage::Japanese=>"コンパイル エラー"};
            VbaCompilationOutcome {compiled:false,error:Some(VbaCompilationDiagnostic {
                kind:"compile",message:format!("{prefix}: {}",failure.error.message(language)),module:failure.module,line:failure.error.span.line,
                procedure:(!failure.error.procedure.is_empty()).then_some(failure.error.procedure),
            })}
        }
    }
}

/// Check the complete project without running code, initializing storage or changing a workbook.
#[wasm_bindgen]
pub fn compile_spreadsheet_vba(source:&str,options:JsValue) -> Result<JsValue,JsError> {
    let options:VbaCompilationOptions=if options.is_null()||options.is_undefined(){VbaCompilationOptions::default()}
        else{serde_wasm_bindgen::from_value(options).map_err(|error|JsError::new(&error.to_string()))?};
    let environment=VbaExecutionOptions {error_language:options.error_language,..VbaExecutionOptions::default()}
        .error_environment().map_err(|error|JsError::new(&error))?;
    let year=options.current_year.unwrap_or_else(this_year_now);
    if !(100..=9999).contains(&year) {return Err(JsError::new("Invalid VBA compilation year."));}
    let mut references=builtin_compilation_references().clone();
    references.current_year=Some(year);
    references.project_name=options.project_name;
    references.types.extend(options.reference_types.into_iter().map(|kind|(kind.name,kind.numeric)));
    references.symbols.extend(options.reference_symbols.into_iter().map(|symbol|(symbol.name,symbol.value)));
    references.namespaces.extend(options.reference_namespaces);
    references.document_modules.extend(options.document_modules.into_iter().filter(|document| !document.host_only).map(|document|(document.name,document.base_type)));
    serde_wasm_bindgen::to_value(&compilation_outcome(source,environment.language,&references)).map_err(|error|JsError::new(&error.to_string()))
}

/// A loaded VBA project's storage and host object identities. Keep this in the
/// workbook's worker between invocations; free it when the workbook closes.
#[wasm_bindgen]
#[derive(Default)]
pub struct SpreadsheetVbaSession {
    state: Option<ProjectSessionState>,
}

fn validate_editor_revision(value: JsValue) -> Result<u64, JsError> {
    if !js_sys::Number::is_safe_integer(&value) || value.as_f64().is_none_or(|number| number < 0.0) {
        return Err(JsError::new("editor revision must be a non-negative safe integer"));
    }
    Ok(value.as_f64().expect("validated number") as u64)
}

#[derive(Serialize)]
struct WorkbookSaveOutput {
    completed: bool,
    saved: bool,
    path: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    package_bytes: Option<Vec<u8>>,
}

#[wasm_bindgen]
impl SpreadsheetVbaSession {
    #[wasm_bindgen(constructor)]
    pub fn new() -> Self { Self::default() }

    /// Adopt the actual owner of objects returned by a single-call run API.
    /// Any reference from that result transfers the whole owner once, including
    /// all sibling references in arrays/records and its module/host storage.
    pub fn from_reference(reference: &str) -> Result<SpreadsheetVbaSession, JsError> {
        take_returned_project(reference).map(|state| Self { state: Some(state) })
            .map_err(|error| JsError::new(&error))
    }

    pub fn compile(&self,source:&str,options:JsValue) -> Result<JsValue,JsError> {
        compile_spreadsheet_vba(source,options)
    }

    /// Compile the loaded project, retaining its storage and tracking its save state.
    /// Unlike `compile`, this operation adopts the workbook and its host context.
    pub fn compile_project(&mut self, workbook: JsValue, source: &str,
        active_sheet: usize, file_name: Option<String>, options: JsValue) -> Result<JsValue, JsError> {
        let request = VbaInvocation { procedure: None, args: js_sys::Array::new().into(),
            action: Some(ExternalObjectAction::CompileProject) };
        let outcome = prepare_spreadsheet_vba(workbook, source, request,
            active_sheet, file_name, options, &mut self.state)?;
        serialize_vba_outcome(&outcome)
    }


    /// Select an existing book without replacing any project's storage or
    /// rebuilding its references. Use the returned source and IR for run/save.
    pub fn select_workbook(&mut self, identity: &str) -> Result<JsValue, JsError> {
        let selection = select_session_workbook(&mut self.state, identity)
            .map_err(|error| JsError::new(&error))?;
        serialize_vba_outcome(&selection)
    }

    /// Preserve pending editor changes before selecting another open book.
    pub fn select_workbook_with_edits(&mut self, identity: &str, workbook: JsValue,
        active_sheet: usize, edit_revision: Option<JsValue>) -> Result<JsValue, JsError> {
        let revision = edit_revision.map(validate_editor_revision).transpose()?;
        let workbook = crate::spreadsheet_workbook_from_js(workbook)
            .map_err(|error| JsError::new(&format!("invalid workbook: {error}")))?;
        let selection = select_session_workbook_with_revision(&mut self.state, identity, workbook, active_sheet, revision)
            .map_err(|error| JsError::new(&error))?;
        serialize_vba_outcome(&selection)
    }

    /// Run the selected workbook's native Save or SaveCopyAs path, including
    /// its callbacks and calculation. Copies leave the original save state.
    pub fn save_workbook(&mut self, workbook: JsValue, source: &str, active_sheet: usize,
        file_name: Option<String>, options: JsValue, copy_name: Option<String>) -> Result<JsValue, JsError> {
        let invocation = VbaInvocation { procedure: None, args: js_sys::Array::new().into(),
            action: Some(ExternalObjectAction::SaveWorkbook { copy_name }) };
        let outcome = prepare_spreadsheet_vba(workbook, source, invocation,
            active_sheet, file_name, options, &mut self.state)?;
        serialize_vba_outcome(&outcome)
    }

    pub fn document_modules(&self,package:&[u8]) -> Result<JsValue,JsError> {
        crate::vba_project::spreadsheet_vba_document_modules(package)
    }

    pub fn run(&mut self, workbook: JsValue, source: &str, procedure: &str, args: JsValue,
        active_sheet: usize, file_name: Option<String>, options: JsValue) -> Result<JsValue, JsError> {
        let outcome = prepare_spreadsheet_vba(workbook, source, VbaInvocation::new(Some(procedure), args), active_sheet, file_name, options, &mut self.state)?;
        serialize_vba_outcome(&outcome)
    }

    /// Invoke a retained reference using { reference, member, kind, args }.
    /// Flags follow VBA CallByName, including combined method/get flag 3.
    pub fn invoke_member(&mut self, workbook: JsValue, source: &str, invocation: JsValue,
        active_sheet: usize, file_name: Option<String>, options: JsValue) -> Result<JsValue, JsError> {
        vba_input_fields(&invocation, &["reference", "member", "kind", "args"], &[])?;
        let reference = vba_input_property(&invocation, "reference")?.as_string()
            .ok_or_else(|| JsError::new("invalid VBA object reference: expected a string"))?;
        let member = vba_input_property(&invocation, "member")?.as_string()
            .ok_or_else(|| JsError::new("invalid VBA member name: expected a string"))?;
        let kind = vba_input_property(&invocation, "kind")?;
        if !js_sys::Number::is_safe_integer(&kind) {
            return Err(JsError::new("invalid VBA call kind: expected a safe integer"));
        }
        let request = VbaInvocation {
            procedure: None, args: vba_input_property(&invocation, "args")?,
            action: Some(ExternalObjectAction::Invoke { reference, member, kind: kind.as_f64().unwrap() as i64 }),
        };
        let outcome = prepare_spreadsheet_vba(workbook, source, request,
            active_sheet, file_name, options, &mut self.state)?;
        serialize_vba_outcome(&outcome)
    }

    /// Release leases against their loaded source, preserving pending editor
    /// changes. Host/workbook/file effects are returned as a normal execution.
    pub fn release_objects(&mut self, workbook: JsValue, references: JsValue,
        active_sheet: usize, file_name: Option<String>, options: JsValue) -> Result<JsValue, JsError> {
        if !js_sys::Array::is_array(&references) {
            return Err(JsError::new("invalid VBA references: expected an array"));
        }
        let references = js_sys::Array::from(&references).iter().map(|value| value.as_string()
            .ok_or_else(|| JsError::new("invalid VBA reference: expected a string")))
            .collect::<Result<Vec<_>, _>>()?;
        self.release_owned_objects(workbook, references, active_sheet, file_name, options)
    }

    /// Release every caller-owned lease, newest first. Project globals and
    /// references retained by VBA continue to own their objects.
    pub fn release_all_objects(&mut self, workbook: JsValue, active_sheet: usize,
        file_name: Option<String>, options: JsValue) -> Result<JsValue, JsError> {
        let references = self.state.as_ref().ok_or_else(|| JsError::new("no loaded VBA project"))?
            .external_references.tokens_in_release_order();
        self.release_owned_objects(workbook, references, active_sheet, file_name, options)
    }

    pub fn prepare_save(&mut self, workbook: JsValue, source: &str, active_sheet: usize,
        file_name: Option<String>, options: JsValue) -> Result<JsValue, JsError> {
        let outcome = prepare_spreadsheet_vba(workbook, source, VbaInvocation::new(None, js_sys::Array::new().into()), active_sheet, file_name, options, &mut self.state)?;
        serialize_vba_outcome(&outcome)
    }
}

impl SpreadsheetVbaSession {
    fn release_owned_objects(&mut self, workbook: JsValue, references: Vec<String>, active_sheet: usize,
        file_name: Option<String>, options: JsValue) -> Result<JsValue, JsError> {
        let source = self.state.as_ref().ok_or_else(|| JsError::new("no loaded VBA project"))?.source.clone();
        let request = VbaInvocation { procedure: None, args: js_sys::Array::new().into(),
            action: Some(ExternalObjectAction::Release { references }) };
        let outcome = prepare_spreadsheet_vba(workbook, &source, request,
            active_sheet, file_name, options, &mut self.state)?;
        serialize_vba_outcome(&outcome)
    }
}

/// Application properties outlive an individual invocation and workbook.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct VbaDirectoryState {
    current_drive: String,
    directories: Vec<String>,
}

impl VbaDirectoryState {
    fn core_state(&self) -> Result<oxivba_core::files::DirectoryState, String> {
        let mut chars=self.current_drive.chars();
        let current_drive=chars.next().filter(|drive| drive.is_ascii_alphabetic())
            .filter(|_| chars.next().is_none()).ok_or_else(|| "directoryState.currentDrive must be one drive letter".to_string())?;
        Ok(oxivba_core::files::DirectoryState {current_drive,directories:self.directories.clone()})
    }

    fn capture(files: &oxivba_core::files::Files) -> Self {
        let state=files.directory_state();
        Self {current_drive:state.current_drive.to_string(),directories:state.directories}
    }

    fn validate(self) -> Result<Self, String> {
        let mut files=oxivba_core::files::Files::default();
        files.restore_directory_state(&self.core_state()?).map_err(|failure|failure.description().to_string())?;
        Ok(Self::capture(&files))
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct VbaCaptionWindow {
    workbook: String,
    prefix_utf16: Vec<u16>,
}

impl VbaCaptionWindow {
    fn capture(settings: &std::collections::HashMap<String, Value>) -> Option<Self> {
        let Value::String(workbook) = settings.get("_caption_window_owner")? else { return None; };
        let prefix_utf16 = settings.get("_caption_window_prefix")?.string_units()?.into_owned();
        Some(Self { workbook: workbook.clone(), prefix_utf16 })
    }
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(default, rename_all = "camelCase", deny_unknown_fields)]
struct VbaStandardFontStartup {
    profile_utf16: Option<Vec<u16>>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(default, rename_all = "camelCase", deny_unknown_fields)]
struct VbaApplicationState {
    calculation: i64,
    calculate_before_save: bool,
    screen_updating: bool,
    enable_events: bool,
    display_alerts: bool,
    status_bar: Option<String>,
    cursor: i64,
    interactive: bool,
    directory_state: Option<VbaDirectoryState>,
    #[serde(skip_serializing_if = "Option::is_none")]
    new_workbook_font: Option<CellStyle>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pending_standard_font_profile_utf16: Option<Vec<u16>>,
    #[serde(skip_serializing)]
    standard_font_startup: Option<VbaStandardFontStartup>,
    #[serde(skip_serializing_if = "Option::is_none")]
    standard_font_preference_present: Option<bool>,
    #[serde(skip_serializing_if = "Option::is_none")]
    caption_suffix_utf16: Option<Vec<u16>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    caption_without_window: Option<bool>,
    #[serde(skip_serializing_if = "Option::is_none")]
    caption_window: Option<VbaCaptionWindow>,
}

impl Default for VbaApplicationState {
    fn default() -> Self {
        Self { calculation: -4105, calculate_before_save: true, screen_updating: true, enable_events: true,
            display_alerts: true, status_bar: None, cursor: CURSOR_DEFAULT, interactive: true, directory_state: None, new_workbook_font: None, pending_standard_font_profile_utf16: None, standard_font_startup: None, standard_font_preference_present: None, caption_suffix_utf16: None, caption_without_window: None, caption_window: None }
    }
}

fn application_state_field_allowed(name: &str) -> bool {
    matches!(name, "calculation" | "calculateBeforeSave" | "screenUpdating" | "enableEvents"
        | "displayAlerts" | "statusBar" | "cursor" | "interactive" | "directoryState"
        | "newWorkbookFont" | "pendingStandardFontProfileUtf16"
        | "standardFontStartup" | "standardFontPreferencePresent"
        | "captionSuffixUtf16" | "captionWithoutWindow" | "captionWindow")
}

impl VbaApplicationState {
    fn validate(mut self) -> Result<Self, String> {
        self.calculation = application_calculation(&Value::Integer(self.calculation))?;
        self.cursor = application_cursor(&Value::Integer(self.cursor))?;
        if let Some(status) = self.status_bar.take() {
            self.status_bar = status_bar_text(&Value::String(status))?;
        }
        self.directory_state=self.directory_state.map(VbaDirectoryState::validate).transpose()?;
        if self.caption_window.as_ref().is_some_and(|window| window.workbook.is_empty()) {
            return Err("captionWindow requires a workbook name".into());
        }
        if let Some(font)=self.new_workbook_font.as_ref() {
            if font.font_name.as_deref().is_none_or(str::is_empty)
                || font.font_size.is_none_or(|size|!size.is_finite() || size<=0.0) {
                return Err("newWorkbookFont requires a face and a finite positive size".into());
            }
        }
        Ok(self)
    }

    fn restore(self, host: &mut WorkbookHost<'_>) {
        host.calculation = self.calculation;
        host.app_settings.insert("calculatebeforesave".to_string(), Value::Boolean(self.calculate_before_save));
        host.screen_updating = self.screen_updating;
        host.enable_events = self.enable_events;
        host.display_alerts = self.display_alerts;
        host.status_bar = self.status_bar;
        host.cursor = self.cursor;
        host.interactive = self.interactive;
        if let Some(font)=self.new_workbook_font {host.application_font=font;}
        let startup_pending = self.standard_font_startup.as_ref().map(|startup| startup.profile_utf16.clone());
        if let Some(startup) = self.standard_font_startup {
            host.application_font = default_application_font();
            if let Some(units) = startup.profile_utf16 {
                let profile = crate::vba_automation::StandardFontProfile(units);
                if let Some((face, points)) = profile.parsed() {
                    host.application_font.font_name = Some(String::from_utf16_lossy(face));
                    host.application_font.font_size = Some(f32::from(points));
                    let reference = host.application_font.font_reference.get_or_insert_with(Default::default);
                    reference.latin_name = None;
                    reference.scheme = None;
                    reference.latin_name_utf16 = String::from_utf16(face).err().map(|_| face.to_vec());
                }
            }
        }
        if let Some(units) = self.pending_standard_font_profile_utf16.or_else(|| startup_pending.clone().flatten()) {
            host.persist_standard_font_profile(crate::vba_automation::StandardFontProfile(units));
        } else {
            host.app_settings.remove("_standard_font_pending_profile");
            if self.standard_font_preference_present == Some(false) || startup_pending == Some(None) {
                host.app_settings.insert("_standard_font_preference_missing".into(), Value::Boolean(true));
            } else {
                host.app_settings.remove("_standard_font_preference_missing");
            }
        }
        host.reset_caption_prefix();
        if let Some(window) = self.caption_window {
            host.app_settings.insert("_caption_window_owner".into(), Value::String(window.workbook));
            host.app_settings.insert("_caption_window_prefix".into(), Value::from_utf16(window.prefix_utf16));
        }
        if self.caption_without_window == Some(true) {
            host.app_settings.insert("_caption_without_window".to_string(), Value::Boolean(true));
        } else {
            host.app_settings.remove("_caption_without_window");
        }
        if let Some(suffix) = self.caption_suffix_utf16.filter(|units| !units.is_empty()) {
            host.app_settings.insert("caption".to_string(), Value::from_utf16(suffix));
        } else {
            host.app_settings.remove("caption");
        }
    }

    fn capture(host: &WorkbookHost<'_>) -> Self {
        Self { calculation: host.calculation, calculate_before_save: host.application_setting("calculatebeforesave") == Some(Value::Boolean(true)), screen_updating: host.screen_updating,
            enable_events: host.enable_events, display_alerts: host.display_alerts,
            status_bar: host.status_bar.clone(), cursor: host.cursor, interactive: host.interactive,
            directory_state: Some(VbaDirectoryState::capture(&host.file_io.files)),
            new_workbook_font: (host.application_font!=default_application_font()).then(||host.application_font.clone()),
        standard_font_startup: None,
        standard_font_preference_present: (host.app_settings.get("_standard_font_preference_missing") == Some(&Value::Boolean(true))).then_some(false),
        pending_standard_font_profile_utf16: host.app_settings.get("_standard_font_pending_profile")
            .and_then(|value| value.string_units()).map(|units| units.into_owned()),
            caption_suffix_utf16: host.app_settings.get("caption").and_then(|value|value.string_units()).map(|units|units.into_owned()),
        caption_without_window: (host.app_settings.get("_caption_without_window") == Some(&Value::Boolean(true))).then_some(true),
            caption_window: VbaCaptionWindow::capture(&host.app_settings) }
    }
}

#[derive(Debug, PartialEq, Serialize)]
struct BrowserMessage {
    prompt: String,
    title: String,
}

#[derive(Debug, PartialEq, Serialize)]
struct ProcedureSummary {
    name: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    module_name: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    module_kind: Option<&'static str>,
    kind: &'static str,
    visibility: &'static str,
    parameter_count: usize,
    required_parameter_count: usize,
    line: u32,
}

fn spreadsheet_vba_procedures(source: &str) -> Result<Vec<ProcedureSummary>, String> {
    spreadsheet_vba_project_procedures(source, &[])
}

fn spreadsheet_vba_project_procedures(source: &str, documents: &[VbaDocumentModule]) -> Result<Vec<ProcedureSummary>, String> {
    let mut summaries = Vec::new();
    for source_module in oxivba_core::source_modules(source) {
        let document = source_module.class && source_module.named.as_ref().is_some_and(|name| documents.iter().any(|document| !document.host_only && document.name.eq_ignore_ascii_case(name)));
        // A predeclared or exposed user class still needs an instance; it is
        // not an Application.Run module. Only host-bound documents qualify.
        if source_module.class && !document { continue; }
        let module = parse_module(&source_module.text).map_err(|error| error.to_string())?;
        summaries.extend(module
        .items
        .iter()
        .filter_map(|item| {
            let ModuleItem::Procedure(procedure) = item else {
                return None;
            };
            let kind = match procedure.kind {
                ProcKind::Sub => "sub",
                ProcKind::Function => "function",
                ProcKind::PropertyGet | ProcKind::PropertyLet | ProcKind::PropertySet => {
                    return None
                }
            };
            let visibility = match procedure.visibility {
                Visibility::Default | Visibility::Public | Visibility::Global => "public",
                Visibility::Private => "private",
                Visibility::Friend => "friend",
            };
            Some(ProcedureSummary {
                name: source_module.named.as_ref().map_or_else(|| procedure.name.clone(), |name| format!("{name}.{}", procedure.name)),
                module_name: source_module.named.clone(),
                module_kind: source_module.named.as_ref().map(|_| if document { "document" } else { "standard" }),
                kind,
                visibility,
                parameter_count: procedure.params.len(),
                required_parameter_count: procedure
                    .params
                    .iter()
                    .filter(|parameter| {
                        !parameter.optional && parameter.mode != ParamMode::ParamArray
                    })
                    .count(),
                line: procedure.span.line.saturating_add((source_module.line as u32).saturating_sub(1)),
            })
        })
        );
    }
    Ok(summaries)
}

/// List executable Sub and Function entry points in VBA source.
#[wasm_bindgen]
pub fn list_spreadsheet_vba_procedures(source: &str) -> Result<JsValue, JsError> {
    let procedures = spreadsheet_vba_procedures(source).map_err(|error| JsError::new(&error))?;
    serde_wasm_bindgen::to_value(&procedures).map_err(|error| JsError::new(&error.to_string()))
}

/// List project entry points using the workbook's document-module identities.
#[wasm_bindgen]
pub fn list_spreadsheet_vba_project_procedures(source: &str, package: &[u8]) -> Result<JsValue, JsError> {
    let documents = if package.is_empty() { Vec::new() } else {
        crate::vba_project::read_document_modules(package).map_err(|error| JsError::new(&error))?
    };
    let procedures = spreadsheet_vba_project_procedures(source, &documents).map_err(|error| JsError::new(&error))?;
    serde_wasm_bindgen::to_value(&procedures).map_err(|error| JsError::new(&error.to_string()))
}

#[derive(Default, Deserialize)]
#[serde(default, rename_all = "camelCase", deny_unknown_fields)]
struct VbaExecutionOptions {
    error_language: Option<String>,
    host_ansi_code_page: Option<u16>,
    worksheet_dbcs_language: Option<bool>,
    vba_help_file: Option<String>,
    project_name: Option<String>,
    application_state: Option<VbaApplicationState>,
    source_edits: Option<Vec<VbaSourceEdit>>,
    document_modules: Option<Vec<VbaDocumentModule>>,
    file_context: Option<file_io::FileContext>,
    file_system_state: Option<file_io::FileSystemState>,
}

#[derive(Clone, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct VbaSourceEdit {
    line: usize,
    delete_lines: usize,
    text: String,
}

impl VbaExecutionOptions {
    fn error_environment(self) -> Result<ErrorEnvironment, String> {
        let language = match self.error_language.as_deref().unwrap_or("en-US").to_ascii_lowercase().as_str() {
            "en" | "en-us" | "en-gb" => ErrorLanguage::English,
            "ja" | "ja-jp" => ErrorLanguage::Japanese,
            language => return Err(format!("unsupported VBA error language: {language}")),
        };
        Ok(ErrorEnvironment { language, help_file: self.vba_help_file.unwrap_or_default() })
    }
}

/// Execute VBA source against an OxiCells workbook IR with English error defaults.
#[wasm_bindgen]
pub fn run_spreadsheet_vba(
    workbook: JsValue,
    source: &str,
    procedure: &str,
    args: JsValue,
    active_sheet: usize,
    file_name: Option<String>,
) -> Result<JsValue, JsError> {
    run_spreadsheet_vba_with_options(workbook, source, procedure, args, active_sheet, file_name, JsValue::UNDEFINED)
}

/// Execute VBA using the selected UI error language and host help-file path.
/// Options: `errorLanguage`, `vbaHelpFile`, the containing VBA `projectName`,
/// `hostAnsiCodePage` (932 or 1252), `worksheetDbcsLanguage` (whether worksheet
/// byte functions use a DBCS default language), and `applicationState` returned by the
/// outcome API's preceding invocation. The host ANSI code page is independent
/// of the error language and the source encoding stored in a VBA project.
#[wasm_bindgen]
pub fn run_spreadsheet_vba_with_options(
    workbook: JsValue,
    source: &str,
    procedure: &str,
    args: JsValue,
    active_sheet: usize,
    file_name: Option<String>,
    options: JsValue,
) -> Result<JsValue, JsError> {
    let outcome = prepare_returned_spreadsheet_vba(workbook, source, VbaInvocation::new(Some(procedure), args), active_sheet, file_name, options)?;
    if let Some(error) = &outcome.error {
        return Err(JsError::new(&error.message));
    }
    serialize_vba_outcome(&outcome.into_result())
}

/// Execute VBA and retain workbook changes and outputs even if the macro fails.
/// Invalid API inputs still throw; execution failures are returned in `error`.
/// Pass the returned `application_state` as the next call's `applicationState`
/// option to preserve the containing Excel application's settings.
/// `fileContext` supplies original `packageBytes`, optional `fullName` and
/// `readOnly`, and initial virtual `folders`/`files`. Produced binary files are
/// returned in `files`; removed paths are returned in `deleted_files`.
#[wasm_bindgen]
pub fn run_spreadsheet_vba_with_outcome(
    workbook: JsValue,
    source: &str,
    procedure: &str,
    args: JsValue,
    active_sheet: usize,
    file_name: Option<String>,
    options: JsValue,
) -> Result<JsValue, JsError> {
    let outcome = prepare_returned_spreadsheet_vba(workbook, source, VbaInvocation::new(Some(procedure), args), active_sheet, file_name, options)?;
    serialize_vba_outcome(&outcome)
}

/// Prepare the workbook for Excel Save, including calculation and VBA UDFs.
/// Serialization remains a separate operation so callers can inspect failures.
#[wasm_bindgen]
pub fn prepare_spreadsheet_vba_save(
    workbook: JsValue,
    source: &str,
    active_sheet: usize,
    file_name: Option<String>,
    options: JsValue,
) -> Result<JsValue, JsError> {
    let outcome = prepare_returned_spreadsheet_vba(workbook, source, VbaInvocation::new(None, js_sys::Array::new().into()), active_sheet, file_name, options)?;
    serialize_vba_outcome(&outcome)
}

fn prepare_returned_spreadsheet_vba(
    workbook: JsValue, source: &str, invocation: VbaInvocation<'_, JsValue>,
    active_sheet: usize, file_name: Option<String>, options: JsValue,
) -> Result<RunOutcome, JsError> {
    let mut state = None;
    let outcome = prepare_spreadsheet_vba(workbook, source, invocation,
        active_sheet, file_name, options, &mut state)?;
    retain_returned_project(state);
    Ok(outcome)
}

fn prepare_spreadsheet_vba(
    workbook: JsValue, source: &str, invocation: VbaInvocation<'_, JsValue>,
    active_sheet: usize, file_name: Option<String>, options: JsValue,
    session: &mut Option<ProjectSessionState>,
) -> Result<RunOutcome, JsError> {
    let VbaInvocation { procedure, args, action } = invocation;
    let options: VbaExecutionOptions = if options.is_null() || options.is_undefined() {
        VbaExecutionOptions::default()
    } else {
        if !options.is_object() || js_sys::Array::is_array(&options) {
            return Err(JsError::new("invalid VBA options: expected an object"));
        }
        // serde-wasm-bindgen reads a struct's known properties directly, so
        // validate object keys as well as the field values it deserializes.
        for name in js_sys::Object::keys(&js_sys::Object::from(options.clone())).iter() {
            let name = name.as_string().unwrap_or_default();
            if !matches!(name.as_str(), "errorLanguage" | "hostAnsiCodePage" | "worksheetDbcsLanguage" | "vbaHelpFile" | "projectName" | "applicationState" | "sourceEdits" | "documentModules" | "fileContext" | "fileSystemState") {
                return Err(JsError::new(&format!("invalid VBA options: unknown field {name}")));
            }
        }
        file_io::validate_context_js(&options)?;
        file_io::validate_snapshot_js(&options)?;
        let edits = js_sys::Reflect::get(&options, &JsValue::from_str("sourceEdits"))
            .map_err(|_| JsError::new("invalid VBA options: cannot read sourceEdits"))?;
        if !edits.is_null() && !edits.is_undefined() {
            if !js_sys::Array::is_array(&edits) { return Err(JsError::new("invalid VBA options: sourceEdits must be an array")); }
            for edit in js_sys::Array::from(&edits).iter() {
                if !edit.is_object() || js_sys::Array::is_array(&edit) { return Err(JsError::new("invalid VBA source edit: expected an object")); }
                for key in js_sys::Object::keys(&js_sys::Object::from(edit.clone())).iter() {
                    let key = key.as_string().unwrap_or_default();
                    if !matches!(key.as_str(), "line" | "deleteLines" | "text") { return Err(JsError::new(&format!("invalid VBA source edit: unknown field {key}"))); }
                }
                for key in ["line", "deleteLines"] {
                    let value = js_sys::Reflect::get(&edit, &JsValue::from_str(key)).map_err(|_| JsError::new("invalid VBA source edit"))?;
                    if !js_sys::Number::is_safe_integer(&value) { return Err(JsError::new(&format!("invalid VBA source edit {key}: expected an integer"))); }
                }
            }
        }
        let state = js_sys::Reflect::get(&options, &JsValue::from_str("applicationState"))
            .map_err(|_| JsError::new("invalid VBA options: cannot read applicationState"))?;
        if !state.is_null() && !state.is_undefined() {
            if !state.is_object() || js_sys::Array::is_array(&state) {
                return Err(JsError::new("invalid VBA options: applicationState must be an object"));
            }
            for name in js_sys::Object::keys(&js_sys::Object::from(state.clone())).iter() {
                let name = name.as_string().unwrap_or_default();
                if !application_state_field_allowed(&name) {
                    return Err(JsError::new(&format!("invalid VBA options: unknown applicationState field {name}")));
                }
            }
            let caption_window = js_sys::Reflect::get(&state, &JsValue::from_str("captionWindow"))
                .map_err(|_| JsError::new("invalid VBA options: cannot read captionWindow"))?;
            if !caption_window.is_null() && !caption_window.is_undefined() {
                if !caption_window.is_object() || js_sys::Array::is_array(&caption_window) {
                    return Err(JsError::new("invalid VBA options: captionWindow must be an object"));
                }
                for name in js_sys::Object::keys(&js_sys::Object::from(caption_window)).iter() {
                    let name = name.as_string().unwrap_or_default();
                    if !matches!(name.as_str(), "workbook" | "prefixUtf16") {
                        return Err(JsError::new(&format!("invalid VBA options: unknown captionWindow field {name}")));
                    }
                }
            }
            let directory=js_sys::Reflect::get(&state,&JsValue::from_str("directoryState"))
                .map_err(|_|JsError::new("invalid VBA options: cannot read directoryState"))?;
            if !directory.is_null() && !directory.is_undefined() {
                if !directory.is_object() || js_sys::Array::is_array(&directory) {
                    return Err(JsError::new("invalid VBA options: directoryState must be an object"));
                }
                for name in js_sys::Object::keys(&js_sys::Object::from(directory)).iter() {
                    let name=name.as_string().unwrap_or_default();
                    if !matches!(name.as_str(),"currentDrive"|"directories") {
                        return Err(JsError::new(&format!("invalid VBA options: unknown directoryState field {name}")));
                    }
                }
            }
        }
        serde_wasm_bindgen::from_value(options)
            .map_err(|error| JsError::new(&format!("invalid VBA options: {error}")))?
    };
    if matches!(&action, Some(ExternalObjectAction::Release { .. })) && options.source_edits.is_some() {
        return Err(JsError::new("invalid VBA source edits: releasing references cannot edit source"));
    }
    let project_name = invocation_project_name(session.as_ref(), options.project_name.as_deref());
    let source_edits = options.source_edits.clone().map(|edits| edits.into_iter().map(|edit| oxivba_core::SourceEdit {
        line: edit.line, delete_lines: edit.delete_lines, text: edit.text,
    }).collect());
    let application_state = options.application_state.clone().map(VbaApplicationState::validate).transpose()
        .map_err(|error| JsError::new(&format!("invalid VBA application state: {error}")))?;
    let document_modules=options.document_modules.clone();
    let file_context=options.file_context.clone();
    let file_system_state=options.file_system_state.clone();
    let host_ansi_code_page=options.host_ansi_code_page.map(AnsiCodePage::from_id).transpose()
        .map_err(|error| JsError::new(&error))?;
    let worksheet_dbcs_language = options.worksheet_dbcs_language;
    let environment = options.error_environment().map_err(|error| JsError::new(&error))?;
    let mut workbook: Workbook = crate::spreadsheet_workbook_from_js(workbook)
        .map_err(|error| JsError::new(&format!("invalid workbook: {error}")))?;
    if let Some(dbcs_language) = worksheet_dbcs_language {
        workbook.calculation.dbcs_language = Some(dbcs_language);
    }
    if !js_sys::Array::is_array(&args){return Err(JsError::new("invalid VBA arguments: expected an array"));}
    let args: Vec<Value> = js_sys::Array::from(&args).iter()
        .map(|value| decode_vba_input_argument_inner(value, &mut Vec::new(),
            session.as_ref().map(|state| &state.external_references))).collect::<Result<_, _>>()?;
    let random_seed =
        js_sys::Date::now().to_bits() ^ js_sys::Math::random().to_bits().rotate_left(17);
    let browser_now = js_sys::Date::new_0();
    let local_millis = browser_now.get_time() - browser_now.get_timezone_offset() * 60_000.0;
    let current_time = local_millis / 86_400_000.0 + 25_569.0;
    execute_workbook_invocation(workbook, source, VbaInvocation { procedure, args, action }, active_sheet,
        VbaRunContext { environment, host_ansi_code_page, project_name, file_name, random_seed, current_time, application_state, source_edits, document_modules, file_context, file_system_state }, session)
        .map_err(|error| JsError::new(&error))
}

