    fn shared_revision_xml_tree(xml: &str) -> serde_json::Value {
        use quick_xml::events::Event;
        fn attributes(element: &quick_xml::events::BytesStart<'_>, reader: &quick_xml::Reader<&[u8]>) -> serde_json::Map<String, serde_json::Value> {
            element.attributes().map(|a| {
                let a=a.unwrap();
                (String::from_utf8(a.key.as_ref().to_vec()).unwrap(),
                 serde_json::Value::String(a.decode_and_unescape_value(reader.decoder()).unwrap().into_owned()))
            }).filter(|(key,_)|key!="xmlns" && !key.starts_with("xmlns:")).collect()
        }

        let mut reader=quick_xml::Reader::from_str(xml);
        let mut stack: Vec<serde_json::Value>=Vec::new();
        loop {
            match reader.read_event().unwrap() {
                Event::Start(e) => stack.push(serde_json::json!({"tag":String::from_utf8_lossy(e.local_name().as_ref()).to_string(),
                    "attributes":attributes(&e,&reader),"text":null,"children":[]})),
                Event::Empty(e) => {
                    let n=serde_json::json!({"tag":String::from_utf8_lossy(e.local_name().as_ref()).to_string(),
                        "attributes":attributes(&e,&reader),"text":null,"children":[]});
                    if let Some(parent)=stack.last_mut() {parent["children"].as_array_mut().unwrap().push(n);}
                    else {return n;}
                }
                Event::Text(e) => {
                    let value=e.unescape().unwrap();
                    if !value.trim().is_empty() {
                        let parent=stack.last_mut().unwrap();
                        let mut held=parent["text"].as_str().unwrap_or_default().to_string();
                        held.push_str(&value);parent["text"]=held.into();
                    }
                }
                Event::End(_) => {
                    let n=stack.pop().unwrap();
                    if let Some(parent)=stack.last_mut() {parent["children"].as_array_mut().unwrap().push(n);}
                    else {return n;}
                }
                Event::Eof => panic!("revision XML has no root"),
                _ => {}
            }
        }
    }

    fn shared_revision_snapshot(bytes: &[u8]) -> serde_json::Value {
        let mut zip=zip::ZipArchive::new(std::io::Cursor::new(bytes)).unwrap();
        let mut logs=Vec::new();let mut header=serde_json::Value::Null;
        for i in 0..zip.len() {
            use std::io::Read;
            let mut part=zip.by_index(i).unwrap();let name=part.name().to_string();
            if name=="xl/revisions/revisionHeaders.xml" || (name.starts_with("xl/revisions/revisionLog") && name.ends_with(".xml")) {
                let mut xml=String::new();part.read_to_string(&mut xml).unwrap();let root=shared_revision_xml_tree(&xml);
                if name.ends_with("revisionHeaders.xml") {header=root;} else {logs.push((name,root));}
            }
        }
        logs.sort_by(|a,b|a.0.cmp(&b.0));
        let changes: Vec<_>=logs.into_iter().flat_map(|(_,root)|root["children"].as_array().unwrap().clone())
            .filter(|n|n["tag"]=="rcc" || n["tag"]=="rfmt").collect();
        let counters: serde_json::Map<_,_>=header["attributes"].as_object().into_iter().flatten()
            .filter(|(key,_)|matches!(key.as_str(),"diskRevisions"|"revisionId"|"version"))
            .map(|(k,v)|(k.clone(),v.clone())).collect();
        serde_json::json!({"header_count":header["children"].as_array().map_or(0,Vec::len),"counters":counters,"changes":changes})
    }

    fn shared_cell_font_snapshot(bytes: &[u8]) -> serde_json::Value {
        let mut archive=oxidocs_common::archive::OoxmlArchive::new(bytes).unwrap();
        let styles=shared_revision_xml_tree(&archive.read_part("xl/styles.xml").unwrap());
        let sheet=shared_revision_xml_tree(&archive.read_part("xl/worksheets/sheet1.xml").unwrap());
        let data=sheet["children"].as_array().unwrap().iter().find(|n|n["tag"]=="sheetData").unwrap();
        let cell=data["children"].as_array().unwrap().iter().flat_map(|row|row["children"].as_array().unwrap())
            .find(|n|n["tag"]=="c" && n["attributes"]["r"]=="A1").unwrap();
        let id=cell["attributes"]["s"].as_str().unwrap_or("0").parse::<usize>().unwrap();
        let children=styles["children"].as_array().unwrap();
        let xfs=children.iter().find(|n|n["tag"]=="cellXfs").unwrap();
        let font=xfs["children"][id]["attributes"]["fontId"].as_str().unwrap_or("0").parse::<usize>().unwrap();
        children.iter().find(|n|n["tag"]=="fonts").unwrap()["children"][font].clone()
    }

    fn shared_unallocated_cell_font_snapshot(bytes: &[u8]) -> serde_json::Value {
        let mut archive=oxidocs_common::archive::OoxmlArchive::new(bytes).unwrap();
        let styles=shared_revision_xml_tree(&archive.read_part("xl/styles.xml").unwrap());
        let children=styles["children"].as_array().unwrap();
        let xfs=children.iter().find(|n|n["tag"]=="cellXfs").unwrap();
        let font=xfs["children"][0]["attributes"]["fontId"].as_str().unwrap_or("0").parse::<usize>().unwrap();
        children.iter().find(|n|n["tag"]=="fonts").unwrap()["children"][font].clone()
    }

    fn shared_cell_rich_text_snapshot(bytes: &[u8]) -> serde_json::Value {
        let mut archive=oxidocs_common::archive::OoxmlArchive::new(bytes).unwrap();
        let sheet=shared_revision_xml_tree(&archive.read_part("xl/worksheets/sheet1.xml").unwrap());
        let data=sheet["children"].as_array().unwrap().iter().find(|n|n["tag"]=="sheetData").unwrap();
        let cell=data["children"].as_array().unwrap().iter().flat_map(|row|row["children"].as_array().unwrap())
            .find(|n|n["tag"]=="c" && n["attributes"]["r"]=="A1").unwrap();
        match cell["attributes"]["t"].as_str() {
            Some("s") => {
                let index=cell["children"].as_array().unwrap().iter().find(|n|n["tag"]=="v").unwrap()["text"]
                    .as_str().unwrap().parse::<usize>().unwrap();
                shared_revision_xml_tree(&archive.read_part("xl/sharedStrings.xml").unwrap())["children"][index]["children"].clone()
            },
            Some("inlineStr") => cell["children"].as_array().unwrap().iter().find(|n|n["tag"]=="is").unwrap()["children"].clone(),
            _ => serde_json::Value::Null,
        }
    }

    fn shared_fixture_styles(package: &[u8], styles: &str) -> Vec<u8> {
        use std::io::{Cursor,Write};
        let mut original=zip::ZipArchive::new(Cursor::new(package)).unwrap();
        let mut output=zip::ZipWriter::new(Cursor::new(Vec::new()));
        for index in 0..original.len() {
            let part=original.by_index(index).unwrap();
            if part.name()=="xl/styles.xml" {
                output.start_file("xl/styles.xml",zip::write::SimpleFileOptions::default()
                    .compression_method(zip::CompressionMethod::Deflated)).unwrap();
                output.write_all(styles.as_bytes()).unwrap();
            } else {output.raw_copy_file(part).unwrap();}
        }
        output.finish().unwrap().into_inner()
    }

    #[test]
    fn shared_revision_content_and_save_boundaries_match_native_excel() {
        const HELPERS: &str = r#"Public Sub SeedOptions(ByVal kind As Long)
 Application.DisplayAlerts = False
 Application.EnableEvents = False
 Dim item As Workbook
 Set item = Workbooks.Open("C:\probe\__PREFIX__-B.xlsm")
 Set item = Workbooks.Open("C:\probe\__PREFIX__-C.xlsm")
 For Each item In Workbooks
 item.Worksheets(1).Range("A2").Value = kind
 item.Saved = True
 Next
End Sub
Public Function OptionProperties() As String
 On Error Resume Next
 Dim target As Workbook, member As Variant, item As Variant, status As Long, result As String
 Set target = Workbooks(1)
 For Each member In Array("ReadOnlyRecommended", "ReadOnly", "CreateBackup", "MultiUserEditing", "ConflictResolution", "WriteReserved", "HasVBProject", "FileFormat")
 Err.Clear
 item = Empty
 item = CallByName(target, CStr(member), vbGet)
 status = Err.Number
 result = result & CStr(member) & "|" & CStr(status) & "|" & CStr(item) & vbLf
 Next
 OptionProperties = result
End Function
"#;
        let seed=include_bytes!("../../../tests/fixtures/vba/array_argument_rank.xlsm");
        let mut rows=Vec::new();
        for group in native_shared_revision_cases().as_array().unwrap() {
            let source=group["source"].as_str().unwrap();let prefix=group["prefix"].as_str().unwrap();
            let root_source=source.replacen("VERSION 1.0 CLASS",&format!("{}\nVERSION 1.0 CLASS",HELPERS.replace("__PREFIX__",prefix)),1);
            let root=crate::vba_project::write_project_source(seed,&root_source,None).unwrap();
            let peer=crate::vba_project::write_project_source(seed,source,None).unwrap();
            for case in group["cases"].as_array().unwrap() {
                let root=case["seed_styles"].as_str().map_or_else(||root.clone(),|styles|shared_fixture_styles(&root,styles));
                let peer=case["seed_styles"].as_str().map_or_else(||peer.clone(),|styles|shared_fixture_styles(&peer,styles));
                let kind=case["kind"].as_i64().unwrap();
                let mut context=failure_context();context.environment.language=ErrorLanguage::Japanese;
                context.file_name=Some(format!("{prefix}-A.xlsm"));
                context.document_modules=Some(crate::vba_project::read_document_modules(&root).unwrap());
                context.file_context=Some(file_io::FileContext {package_bytes:Some(root.clone()),full_name:Some(format!(r"C:\probe\{prefix}-A.xlsm")),
                    folders:vec![r"C:\probe".into()],files:["B","C"].into_iter().map(|name|file_io::ProducedFile {
                        path:format!(r"C:\probe\{prefix}-{name}.xlsm"),bytes:peer.clone()}).collect(),..Default::default()});
                let mut session=None;
                let setup=execute_workbook_action_in_session(oxicells_core::parse_xlsx_preserving_values(&root).unwrap(),&root_source,
                    Some("Driver.SeedOptions"),vec![Value::Integer(kind)],0,context,&mut session).unwrap();
                assert!(setup.error.is_none());
                let view=select_session_workbook(&mut session,"1").unwrap();
                let out=close_fixture_run(view.selected.workbook,&view.selected.source,"Driver.Probe",vec![Value::Integer(kind)],&view.selected.name,&mut session);
                let state=serde_json::to_value(&out.file_system_state).unwrap();
                let files: Vec<file_io::ProducedFile>=serde_json::from_value(state["files"].clone()).unwrap();
                let mut checks=BTreeMap::new();
                checks.insert("no_unhandled_error".to_string(),out.error.is_none());
                let mut actual=serde_json::to_value(&out.result).unwrap()["value"].as_str().unwrap_or_default().to_string();
                if group["native_field"]=="workbook_save_as_shared_revision_boundaries_native_v1" && kind==5 {
                    if let Some((before,after))=actual.split_once(r"C:\probe\save-options-shared-boundaries-missing\") {
                        if let Some((token,tail))=after.split_once('\'') {
                            if token.len()==8 && token.bytes().all(|c|c.is_ascii_hexdigit() && !c.is_ascii_lowercase()) {
                                actual=format!("{before}C:\\probe\\save-options-shared-boundaries-missing\\<NativeTemp8Hex>'{tail}");
                            }
                        }
                    }
                }
                checks.insert("probe_value".into(),actual==case["value"]);
                let log=files.iter().find(|f|f.path.eq_ignore_ascii_case(&format!(r"C:\probe\{prefix}-events.txt")))
                    .map(|f|String::from_utf8_lossy(&f.bytes).replace("\r\n","\n")).unwrap_or_default();
                checks.insert("event_trace".into(),log==case["event_log"]);
                let mut snapshots=BTreeMap::new();
                for (label,name) in [("saved",case["destination"].as_str().unwrap().to_string()),("intermediate",format!("{prefix}-intermediate.xlsm"))] {
                    if let Some(expected)=case["snapshots"].get(label) {
                        let file=files.iter().find(|f|f.path.eq_ignore_ascii_case(&format!(r"C:\probe\{name}")));
                        if std::env::var("OXI_VBA_CAPTURE_REVISION_PACKAGES").as_deref()==Ok("1") {
                            if let Some(file)=file { println!("OXI_VBA_SHARED_REVISION_PACKAGE {}",serde_json::json!({
                                "native_field":group["native_field"],"kind":kind,"label":label,"path":file.path,"bytes":file.bytes})); }
                        }
                        let snapshot=file.map(|f|shared_revision_snapshot(&f.bytes)).unwrap_or_default();
                        checks.insert(format!("{label}_history"),snapshot==*expected);snapshots.insert(label.to_string(),snapshot);
                        if let Some(expected)=case.get("font_metadata").and_then(|v|v.get(label)) {
                            let font=file.map(|f|shared_cell_font_snapshot(&f.bytes)).unwrap_or_default();
                            checks.insert(format!("{label}_font"),font==*expected);snapshots.insert(format!("{label}_font"),font);
                        }
                        if let Some(expected)=case.get("rich_text").and_then(|v|v.get(label)) {
                            let rich=file.map(|f|shared_cell_rich_text_snapshot(&f.bytes)).unwrap_or_default();
                            checks.insert(format!("{label}_rich_text"),rich==*expected);snapshots.insert(format!("{label}_rich_text"),rich);
                        }
                    }
                }
                let view=select_session_workbook(&mut session,"1").unwrap();
                let copied=close_fixture_run(view.selected.workbook,&view.selected.source,"Driver.CopyAndReopen",vec![],&view.selected.name,&mut session);
                let value=serde_json::to_value(&copied.result).unwrap();
                checks.insert("copy_value".into(),copied.error.is_none() && value["value"]==case["copy_reopen"]);
                let state=serde_json::to_value(&copied.file_system_state).unwrap();
                let files: Vec<file_io::ProducedFile>=serde_json::from_value(state["files"].clone()).unwrap();
                let file=files.iter().find(|f|f.path.eq_ignore_ascii_case(&format!(r"C:\probe\{prefix}-copy.xlsm")));
                if std::env::var("OXI_VBA_CAPTURE_REVISION_PACKAGES").as_deref()==Ok("1") {
                    if let Some(file)=file { println!("OXI_VBA_SHARED_REVISION_PACKAGE {}",serde_json::json!({
                        "native_field":group["native_field"],"kind":kind,"label":"copy","path":file.path,"bytes":file.bytes})); }
                }
                let snapshot=file.map(|f|shared_revision_snapshot(&f.bytes)).unwrap_or_default();
                checks.insert("copy_history".into(),snapshot==case["snapshots"]["copy"]);snapshots.insert("copy".to_string(),snapshot);
                if let Some(expected)=case.get("font_metadata").and_then(|v|v.get("copy")) {
                    let font=file.map(|f|shared_cell_font_snapshot(&f.bytes)).unwrap_or_default();
                    checks.insert("copy_font".into(),font==*expected);snapshots.insert("copy_font".to_string(),font);
                }
                if let Some(expected)=case.get("rich_text").and_then(|v|v.get("copy")) {
                    let rich=file.map(|f|shared_cell_rich_text_snapshot(&f.bytes)).unwrap_or_default();
                    checks.insert("copy_rich_text".into(),rich==*expected);snapshots.insert("copy_rich_text".to_string(),rich);
                }
                let row=serde_json::json!({"native_field":group["native_field"],"kind":kind,"checks":checks,
                    "match":checks.values().all(|v|*v),"actual_value":actual,"actual_event_log":log,"snapshots":snapshots});
                if std::env::var("OXI_VBA_CAPTURE_SHARED_REVISIONS").as_deref()==Ok("1") {println!("OXI_VBA_SHARED_REVISION_CASE {row}");}
                rows.push(row);
            }
        }
        let failed: Vec<_>=rows.iter().filter(|r|r["match"]==false).collect();
        println!("OXI_VBA_SHARED_REVISION_SUMMARY {}",serde_json::json!({"compared":rows.len(),"mismatches":failed.len(),
            "failed_cases":failed.iter().map(|r|serde_json::json!({"native_field":r["native_field"],"kind":r["kind"],
                "failed_checks":r["checks"].as_object().unwrap().iter().filter_map(|(k,v)|(v==false).then_some(k)).collect::<Vec<_>>()})).collect::<Vec<_>>()}));
        assert_eq!(rows.len(),208);assert!(failed.is_empty(),"{} Native shared revision mismatches",failed.len());
    }

