        const CODE:&str=r####"Attribute VB_Name = "DrawingIdentityProbe"
Option Explicit
Private Function H(ByVal text As String) As String
 Dim i As Long
 For i = 1 To Len(text)
  H = H & Right$("0000" & Hex$(AscW(Mid$(text, i, 1)) And &HFFFF&), 4)
 Next i
End Function
Private Function V(ByVal item As Variant) As String
 If IsNull(item) Then
  V = CStr(VarType(item)) & ":NULL"
 Else
  V = CStr(VarType(item)) & ":" & CStr(item)
 End If
End Function
Private Function Flags(ByVal ws As Worksheet) As String
 Flags = V(ws.Range("C3:D4").HasArray) & ";" & V(ws.Range("B3,C3").HasArray) & ";" & V(ws.Range("C3,C8").HasArray) & ";" & V(ws.Range("C8,C3").HasArray)
End Function
Private Function State(ByVal ws As Worksheet) As String
 State = "PENDING=" & Flags(ws)
 State = State & ";USED=" & ws.UsedRange.Address(0, 0)
 State = State & ";CURRENT=" & Flags(ws) & ";B99=" & V(ws.Range("B99").Font.Name) & ":" & V(ws.Range("B99").Font.Size) & ":" & V(ws.Range("B99").Font.Bold) & ":" & V(ws.Range("B99").NumberFormat)
End Function
Public Function Measure(ByVal inputPath As String, ByVal outputPath As String, ByVal unused1 As String, ByVal unused2 As String, ByVal mode As Long) As String
 Dim wb As Workbook, ws As Worksheet, text As String, focus As Range
 On Error GoTo Failed
 Set wb = Workbooks.Add
 Set ws = wb.Worksheets(1)
 If mode = 2 Then
  wb.Styles("Normal").Font.Name = "Arial"
  wb.Styles("Normal").Font.Size = 14
 End If
 ws.Range("C3:C4").FormulaArray = "=ROW(A1:A2)"
 ws.Range("A1").Value2 = 1
 ws.Range("K8").Value2 = 1
 Select Case mode
  Case 3: ws.Columns("B").Font.Bold = True
  Case 4: ws.Rows(99).Font.Bold = True
  Case 5: ws.Cells.Font.Size = 16
  Case 6: ws.Columns("B").NumberFormat = "0.00"
 End Select
 If mode <= 1 Then
  Set focus = ws.Range("A20")
 Else
  Set focus = ws.Range("B99")
 End If
 If mode = 0 Or mode = 7 Then
  focus.Value2 = "temporary"
 Else
  focus.Font.Italic = True
 End If
 text = "LIVE|BEFORE|" & State(ws)
 If mode = 0 Or mode = 7 Then
  focus.Clear
 Else
  focus.ClearFormats
 End If
 ws.Range("K8").Clear
 ws.Range("A1").Clear
 text = text & "|CLEARED|" & State(ws)
 wb.SaveAs outputPath, 51
 text = text & "|SAVED|" & State(ws)
 Set focus = Nothing
 Set ws = Nothing
 wb.Close False
 Set wb = Workbooks.Open(outputPath, UpdateLinks:=0)
 text = text & "|REOPEN|" & State(wb.Worksheets(1))
 wb.Close False
 Measure = H(text)
 Exit Function
Failed:
 text = text & "|ERROR|" & CStr(Err.Number) & "|" & Err.Description
 On Error Resume Next
 If Not wb Is Nothing Then wb.Close False
 Measure = H(text)
End Function
"####;
