    #[test]
    fn standard_font_startup_cache_matches_native_and_is_not_reapplied() {
        let source = r####"Attribute VB_Name = "FontRestartProbe"
Option Explicit
Public Function Change(ByVal mode As Long) As String
 Select Case mode
 Case 0: Application.StandardFont = "Arial": Application.StandardFontSize = 13.75
 Case 1: Application.StandardFont = "Arial": Application.StandardFontSize = 0.975
 Case 2: Application.StandardFont = "Arial": Application.StandardFontSize = 409.55
 Case 3: Application.StandardFontSize = 13: Application.StandardFont = ""
 Case 4: Application.StandardFont = "Arial,13"
 End Select
 Change = Observe()
End Function
Public Function Observe() As String
 Dim text As String
 Dim added As Workbook
 On Error GoTo Failed
 text = "APP|" & Describe(Application.StandardFont) & "|" & Describe(Application.StandardFontSize)
 text = text & "|CURRENT|" & Describe(ThisWorkbook.Worksheets(1).Range("A1").Font.Name) & "|" & Describe(ThisWorkbook.Worksheets(1).Range("A1").Font.Size)
 text = text & "|SAVED|" & CStr(ThisWorkbook.Saved)
 Set added = Workbooks.Add
 text = text & "|NEW|" & Describe(added.Worksheets(1).Range("A1").Font.Name) & "|" & Describe(added.Worksheets(1).Range("A1").Font.Size)
 text = text & "|NORMAL|" & Describe(added.Styles.Item(1).Font.Name) & "|" & Describe(added.Styles.Item(1).Font.Size)
 text = text & "|THEME|" & Describe(added.Worksheets(1).Range("A1").Font.ThemeFont)
 text = text & "|HEIGHT|" & Describe(added.Worksheets(1).Range("A1").RowHeight)
 text = text & "|WIDTH|" & Describe(added.Worksheets(1).Range("A1").ColumnWidth)
 added.Close False
 Set added = Nothing
 Observe = UnitHex(text)
 Exit Function
Failed:
 text = text & "|ERR|" & CStr(Err.Number) & "|" & Err.Source & "|" & Err.Description
 On Error Resume Next
 If Not added Is Nothing Then added.Close False
 Observe = UnitHex(text)
End Function
Private Function Describe(ByVal value As Variant) As String
 Describe = TypeName(value) & ":" & CStr(VarType(value)) & ":" & CStr(value)
End Function
Private Function UnitHex(ByVal text As String) As String
 Dim i As Long
 For i = 1 To Len(text)
  UnitHex = UnitHex & Right$("0000" & Hex$(AscW(Mid$(text, i, 1)) And &HFFFF&), 4)
 Next i
End Function
"####;
        let cases: &[(&str,Option<&[u16]>,&str)] = &[(r####"fraction13point75"####,Some(&[65,114,105,97,108,44,49,51,46,55,53]),r####""####),(r####"minimum0point975"####,Some(&[65,114,105,97,108,44,48,46,57,55,53]),r####""####),(r####"maximum409point55"####,Some(&[65,114,105,97,108,44,52,48,57,46,53,53]),r####""####),(r####"empty_face"####,Some(&[44,49,51]),r####""####),(r####"comma_face"####,Some(&[65,114,105,97,108,44,49,51,44,49,49]),r####""####),(r####"missing"####,None,r####""####),(r####"lone_high"####,Some(&[55296,44,49,51]),r####""####),(r####"lone_low"####,Some(&[56320,44,49,51]),r####""####),(r####"astral_face"####,Some(&[55357,56832,44,49,51]),r####""####),(r####"explicit_original"####,Some(&[28216,12468,12471,12483,12463,44,49,49]),r####""####)];
        for &(id, profile, expected_hex) in cases {
            let mut context = failure_context();
            context.application_state = Some(VbaApplicationState {standard_font_startup:Some(VbaStandardFontStartup {
                profile_utf16:profile.map(<[u16]>::to_vec)}),..Default::default()});
            let mut session = None;
            let first = execute_workbook_action_in_session(workbook(),source,Some("FontRestartProbe.Observe"),vec![],0,context,&mut session).unwrap();
            assert!(first.error.is_none(),"{id}: {:?}",first.error.as_ref().map(|error|&error.message));
            let decode = |hex:&str| (0..hex.len()).step_by(4).map(|at|u16::from_str_radix(&hex[at..at+4],16).unwrap()).collect::<Vec<_>>();
            let expected = decode(expected_hex);
            let json = serde_json::to_value(&first.result).unwrap();let actual = decode(json["value"].as_str().unwrap());
            let separator=u16::from(b'|');let actual=actual.split(|u|*u==separator).collect::<Vec<_>>();let expected=expected.split(|u|*u==separator).collect::<Vec<_>>();
            for label in ["APP","NEW","NORMAL","THEME"] {
                let key=label.encode_utf16().collect::<Vec<_>>();let a=actual.iter().position(|v|*v==key.as_slice()).unwrap();let b=expected.iter().position(|v|*v==key.as_slice()).unwrap();
                assert_eq!(actual[a+1],expected[b+1],"{id} {label}");
                if label!="THEME" {assert_eq!(actual[a+2],expected[b+2],"{id} {label} size");}
            }
            let wire=serde_json::to_value(&first.application_state).unwrap();
            assert!(wire.get("standardFontStartup").is_none());
            assert_eq!(first.application_state.pending_standard_font_profile_utf16.as_deref(),profile);
            assert_eq!(first.application_state.standard_font_preference_present,profile.is_none().then_some(false));
            let mut context=failure_context();context.application_state=Some(first.application_state);
            let second=execute_workbook_action_in_session(first.workbook,source,Some("FontRestartProbe.Observe"),vec![],0,context,&mut session).unwrap();
            assert!(second.error.is_none());assert_eq!(serde_json::to_value(&second.result).unwrap(),json);
        }
    }

