    #[test]
    fn visual_condition_value_visibility_survives_save() {
        let bytes = include_bytes!("../../../tests/fixtures/conditional/visual_rules.xlsx");
        for (setup, bar_cell, icon_cell) in [
            ("", "B2", "C2"),
            ("Cells.FormatConditions.Delete\nRange(\"B2:B6\").FormatConditions.AddDatabar\nRange(\"C2:C6\").FormatConditions.AddIconSetCondition\n", "B2", "C2"),
        ] {
            let source = format!("Public Function Change() As String\n{setup}Dim b As Object, i As Object, s As String\nSet b=Range(\"{bar_cell}\").FormatConditions(1): Set i=Range(\"{icon_cell}\").FormatConditions(1)\ns=ReadRule() & \";\"\nb.ShowValue=False: i.ShowIconOnly=True: i.ReverseOrder=True\ns=s & ReadRule() & \";\"\nb.ShowValue=\"0\": i.ShowIconOnly=2\nChange=s & ReadRule()\nEnd Function\nPublic Function ResetRule() As String\nRange(\"{bar_cell}\").FormatConditions(1).ShowValue=True\nRange(\"{icon_cell}\").FormatConditions(1).ShowIconOnly=False\nRange(\"{icon_cell}\").FormatConditions(1).ReverseOrder=False\nResetRule=ReadRule()\nEnd Function\nPublic Function ReadRule() As String\nDim b As Object, i As Object\nSet b=Range(\"{bar_cell}\").FormatConditions(1): Set i=Range(\"{icon_cell}\").FormatConditions(1)\nReadRule=CStr(b.ShowValue) & \"|\" & CStr(i.ShowIconOnly) & \"|\" & CStr(i.ReverseOrder)\nEnd Function");
            let result = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), &source, Some("Change"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "{:?}", result.error.as_ref().map(|error| &error.message));
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":"True|False|False;False|True|True;False|True|True"}));
            let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap(); editor.apply_workbook(&result.workbook).unwrap();
            let saved = editor.save().unwrap();
            let reopened = oxicells_core::parse_xlsx(&saved).unwrap();
            let bar = reopened.sheets[0].conditional_rules.iter().find(|rule| rule.kind == "dataBar").unwrap();
            assert!(bar.visual_xml.as_deref().unwrap().contains("showValue=\"0\""));
            if setup.is_empty() { assert!(bar.visual_extension_xml.as_deref().unwrap().contains("axisPosition=\"middle\"")); }
            let icons = reopened.sheets[0].conditional_rules.iter().find(|rule| rule.kind == "iconSet").unwrap();
            assert!(icons.visual_xml.as_deref().unwrap().contains("reverse=\"1\""));
            let result = execute_workbook_action_in_session(reopened, &source, Some("ReadRule"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "{:?}", result.error.as_ref().map(|error| &error.message));
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":"False|True|True"}));
            let result = execute_workbook_action_in_session(result.workbook, &source, Some("ResetRule"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "{:?}", result.error.as_ref().map(|error| &error.message));
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":"True|False|False"}));
            let mut editor = oxicells_core::XlsxEditor::new(&saved).unwrap(); editor.apply_workbook(&result.workbook).unwrap();
            let reopened = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
            let result = execute_workbook_action_in_session(reopened, &source, Some("ReadRule"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none());
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":"True|False|False"}));
        }
    }

