    #[test]
    fn deleting_extended_data_bar_preserves_other_conditional_rules() {
        let bytes = include_bytes!("../../../tests/fixtures/conditional/visual_rules.xlsx");
        for (target, expected, extension) in [
            ("B2", "1|0|1|4|$B$3:$B$6|2", Some("<xm:sqref>B3:B6</xm:sqref>")),
            ("B2:B6", "1|0|1|0", None),
        ] {
            let source = format!("Public Function Change() As String\nRange(\"{target}\").FormatConditions.Delete\nChange=ReadRule()\nEnd Function\nPublic Function ReadRule() As String\nDim c As Object\nReadRule=CStr(Range(\"A2\").FormatConditions.Count) & \"|\" & CStr(Range(\"B2\").FormatConditions.Count) & \"|\" & CStr(Range(\"C2\").FormatConditions.Count) & \"|\" & CStr(Range(\"B3\").FormatConditions.Count)\nIf Range(\"B3\").FormatConditions.Count > 0 Then\nSet c=Range(\"B3\").FormatConditions(1)\nReadRule=Left(ReadRule,Len(ReadRule)-1) & CStr(c.Type) & \"|\" & c.AppliesTo.Address & \"|\" & CStr(c.Priority)\nEnd If\nEnd Function");
            let result = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), &source, Some("Change"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "{target}: {:?}", result.error.as_ref().map(|error| &error.message));
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "{target}");
            let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
            editor.apply_workbook(&result.workbook).unwrap();
            let saved = editor.save().unwrap();
            let xml = oxidocs_common::archive::OoxmlArchive::new(&saved).unwrap().read_part("xl/worksheets/sheet1.xml").unwrap();
            if let Some(extension) = extension { assert!(xml.contains(extension)); }
            else { assert!(!xml.contains("x14:conditionalFormattings")); }
            assert!(xml.contains("<iconSet>"));
            let reopened = oxicells_core::parse_xlsx(&saved).unwrap();
            let result = execute_workbook_action_in_session(reopened, &source, Some("ReadRule"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "{target}: {:?}", result.error.as_ref().map(|error| &error.message));
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "reopened: {target}");
        }
    }

