    #[test]
    fn worksheet_shape_ids_survive_save_copy_and_reopen() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/cell_width.xlsm");
        let seed = parse_module(r#"Public Function Seed() As String
 Dim removed As Shape, kept As Shape, chart As ChartObject
 Set removed = Worksheets(1).Shapes.AddShape(1, 1, 1, 20, 20)
 Set kept = Worksheets(1).Shapes.AddShape(1, 30, 1, 20, 20)
 kept.Name = "Kept"
 removed.Delete
 Set chart = Worksheets(1).ChartObjects.Add(1, 40, 100, 100)
 chart.Name = "Revenue"
 Seed = CStr(kept.ID) & "|" & CStr(Worksheets(1).Shapes("Revenue").ID)
End Function
Public Function CopySheet() As String
 Worksheets(1).Copy After:=Worksheets(1)
 CopySheet = CStr(Worksheets(1).Shapes("Kept").ID) & "|" & CStr(Worksheets(1).Shapes("Revenue").ID) & "|" & CStr(Worksheets(2).Shapes("Kept").ID) & "|" & CStr(Worksheets(2).Shapes("Revenue").ID)
End Function
"#).unwrap();
        let mut book = oxicells_core::parse_xlsx(bytes).unwrap();
        {
            let mut host = WorkbookHost::new(&mut book, 0).unwrap();
            assert_eq!(execute_with_host(&seed, "Seed", vec![], &mut host).unwrap(), Value::String("3|4".into()));
        }
        let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
        editor.apply_workbook(&book).unwrap();
        let saved = editor.save().unwrap();
        let mut reopened = oxicells_core::parse_xlsx(&saved).unwrap();
        assert_eq!(reopened.sheets[0].drawings.iter().map(|drawing| drawing.non_visual_id).collect::<Vec<_>>(), vec![Some(3), Some(4)]);
        // Host startup also normalizes formula spill metadata. Check the
        // drawing/note IR here; the unchanged-save byte controls remain below.
        let unchanged = serde_json::to_value((&reopened.sheets[0].drawings,
            &reopened.sheets[0].comments, &reopened.sheets[0].drawing_id_blocks)).unwrap();
        {
            let host = WorkbookHost::new(&mut reopened, 0).unwrap();
            assert_eq!(host.shapes.len(), 2);
        }
        assert_eq!(serde_json::to_value((&reopened.sheets[0].drawings,
            &reopened.sheets[0].comments, &reopened.sheets[0].drawing_id_blocks)).unwrap(), unchanged,
            "read-only drawing adoption must not edit drawing/note metadata");
        {
            let mut host = WorkbookHost::new(&mut reopened, 0).unwrap();
            assert_eq!(execute_with_host(&seed, "CopySheet", vec![], &mut host).unwrap(), Value::String("3|4|2|3".into()));
        }
        let mut editor = oxicells_core::XlsxEditor::new(&saved).unwrap();
        editor.apply_workbook(&reopened).unwrap();
        let copied = editor.save().unwrap();
        let reopened = oxicells_core::parse_xlsx(&copied).unwrap();
        assert_eq!(reopened.sheets[0].drawings.iter().map(|drawing| drawing.non_visual_id).collect::<Vec<_>>(), vec![Some(3), Some(4)]);
        assert_eq!(reopened.sheets[1].drawings.iter().map(|drawing| drawing.non_visual_id).collect::<Vec<_>>(), vec![Some(2), Some(3)]);
        let mut no_edit = oxicells_core::XlsxEditor::new(&copied).unwrap();
        no_edit.apply_workbook(&reopened).unwrap();
        assert_eq!(no_edit.save().unwrap(), copied);
        const GENERATED: &str = r#"Public Function Generated(ByVal custom As Boolean) As String
 Dim wb As Workbook, ws As Worksheet, first As Shape, box As Shape, text As String
 Set wb = Workbooks.Open("C:\probe\generated-input.xlsx")
 Set ws = wb.Worksheets(1)
 Set first = ws.Shapes.AddShape(1, 1, 1, 10, 10)
 Set box = ws.Shapes.AddTextbox(1, 20, 1, 30, 20)
 If custom Then box.Name = "TextBox 2"
 first.Delete
 wb.SaveAs "C:\probe\generated-result.xlsx", 51
 Set first = Nothing
 Set box = Nothing
 Set ws = Nothing
 wb.Close False
 Set wb = Workbooks.Open("C:\probe\generated-result.xlsx")
 text = wb.Worksheets(1).Shapes(1).Name & ":" & CStr(wb.Worksheets(1).Shapes(1).Type)
 wb.Worksheets(1).Copy After:=wb.Worksheets(1)
 text = text & "|" & wb.Worksheets(2).Shapes(1).Name & ":" & CStr(wb.Worksheets(2).Shapes(1).Type)
 wb.Save
 wb.Close False
 Set wb = Workbooks.Open("C:\probe\generated-result.xlsx")
 text = text & "|" & wb.Worksheets(2).Shapes(1).Name & ":" & CStr(wb.Worksheets(2).Shapes(1).ID)
 wb.Close False
 Generated = text
End Function"#;
        for custom in [false, true] {
            let mut context = failure_context();
            context.file_name = Some("generated-code.xlsm".into());
            context.file_context = Some(file_io::FileContext {
                full_name: Some(r"C:\probe\generated-code.xlsm".into()), package_bytes: Some(bytes.to_vec()),
                folders: vec![r"C:\probe".into()], files: vec![file_io::ProducedFile {
                    path: r"C:\probe\generated-input.xlsx".into(), bytes: include_bytes!("../../../tests/fixtures/basic_test.xlsx").to_vec()
                }], ..Default::default()
            });
            let out = execute_workbook_action_in_session(oxicells_core::parse_xlsx_preserving_values(bytes).unwrap(),
                GENERATED, Some("Generated"), vec![Value::Boolean(custom)], 0, context, &mut None).unwrap();
            assert!(out.error.is_none(), "{:?}", out.error.as_ref().map(|error| &error.message));
            let copied_name = if custom { "TextBox 2" } else { "TextBox 1" };
            assert_eq!(serde_json::to_value(&out.result).unwrap()["value"], format!("TextBox 2:17|{copied_name}:17|{copied_name}:2"));
            let state = serde_json::to_value(&out.file_system_state).unwrap();
            let files: Vec<file_io::ProducedFile> = serde_json::from_value(state["files"].clone()).unwrap();
            let saved = files.iter().find(|file|file.path.ends_with("generated-result.xlsx")).unwrap();
            let parsed = oxicells_core::parse_xlsx(&saved.bytes).unwrap();
            assert_eq!(parsed.sheets[1].drawings[0].non_visual_id, Some(2));
            let oxicells_core::ir::DrawingKind::Shape(shape) = &parsed.sheets[1].drawings[0].kind else { panic!("text box expected") };
            assert!(shape.text_box);
        }

        // Native71/72/73: equal names retain distinct physical identities.
        // Save/SaveAs keep existing handles and establish a new source for
        // the next edit; worksheet copying must not redirect that edit.
        const DUPLICATED: &str = r#"Public Function DuplicateIdentity() As String
 Dim wb As Workbook, ws As Worksheet, original As Shape, duplicate As Object, text As String
 Set wb = Workbooks.Open("C:\probe\duplicate-input.xlsx")
 Set ws = wb.Worksheets(1)
 Set original = ws.Shapes.AddShape(1, 10, 10, 30, 20)
 original.Name = "Box"
 Set duplicate = original.Duplicate
 text = original.Name & ":" & CStr(original.ID) & "|" & duplicate.Name & ":" & CStr(duplicate.ID) & "|" & CStr(duplicate.Left)
 wb.SaveAs "C:\probe\duplicate-result.xlsx", 51
 duplicate.Left = 100.25
 wb.Save
 text = text & "|" & CStr(duplicate.Left)
 ws.Copy After:=ws
 ActiveSheet.Shapes(2).Name = "Renamed Copy"
 wb.Save
 Set original = Nothing
 Set duplicate = Nothing
 Set ws = Nothing
 wb.Close False
 Set wb = Workbooks.Open("C:\probe\duplicate-result.xlsx")
 Set ws = wb.Worksheets(1)
 text = text & "|" & ws.Shapes(1).Name & ":" & CStr(ws.Shapes(1).ID) & ":" & CStr(ws.Shapes(1).Left)
 text = text & "|" & ws.Shapes(2).Name & ":" & CStr(ws.Shapes(2).ID) & ":" & CStr(ws.Shapes(2).Left)
 Set ws = wb.Worksheets(2)
 text = text & "|" & ws.Shapes(1).Name & ":" & CStr(ws.Shapes(1).ID) & "|" & ws.Shapes(2).Name & ":" & CStr(ws.Shapes(2).ID)
 wb.Close False
 DuplicateIdentity = text
End Function"#;
        let mut context=failure_context();
        context.file_name=Some("duplicate-code.xlsm".into());
        context.file_context=Some(file_io::FileContext {
            full_name:Some(r"C:\probe\duplicate-code.xlsm".into()),package_bytes:Some(bytes.to_vec()),
            folders:vec![r"C:\probe".into()],files:vec![file_io::ProducedFile {
                path:r"C:\probe\duplicate-input.xlsx".into(),bytes:include_bytes!("../../../tests/fixtures/basic_test.xlsx").to_vec()
            }],..Default::default()
        });
        let out=execute_workbook_action_in_session(oxicells_core::parse_xlsx_preserving_values(bytes).unwrap(),
            DUPLICATED,Some("DuplicateIdentity"),vec![],0,context,&mut None).unwrap();
        assert!(out.error.is_none(),"{:?}",out.error.as_ref().map(|error|&error.message));
        assert_eq!(serde_json::to_value(&out.result).unwrap()["value"],"Box:2|Box:3|22|100.25|Box:2:10|Box:3:100.25|Box:2|Renamed Copy:3");
        let pasted=parse_module(r#"Public Function PasteAtOrigin() As String
 Dim source As Shape, copy As Shape, line As Shape
 Set source = ActiveSheet.Shapes.AddShape(1, 10, 10, 30, 20)
 source.Name = "MyBox"
 source.Copy
 ActiveSheet.Paste
 Set copy = ActiveSheet.Shapes(ActiveSheet.Shapes.Count)
 Set line = ActiveSheet.Shapes.AddLine(10, 10, 40, 30)
 PasteAtOrigin = CStr(copy.Left) & "|" & CStr(copy.Top) & "|" & copy.Name & "|" & CStr(copy.ID) & "|" & CStr(line.Fill.ForeColor.RGB)
End Function"#).unwrap();
        let mut book=oxicells_core::parse_xlsx_preserving_values(bytes).unwrap();
        let mut host=WorkbookHost::new(&mut book,0).unwrap();
        assert_eq!(execute_with_host(&pasted,"PasteAtOrigin",vec![],&mut host).unwrap(),Value::String("0|0|MyBox|3|0".into()));


    }

    #[test]
    fn worksheet_shape_note_block_boundaries_match_excel_and_survive_save() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/cell_width.xlsm");
        let module = parse_module(r#"Public Function Notes(ByVal count As Long, ByVal copy As Boolean) As String
 Dim source As Worksheet, extra As Worksheet, copied As Worksheet, i As Long
 Set source = Worksheets(1)
 Set extra = Worksheets.Add(After:=source)
 extra.Name = "Extra"
 For i = 1 To count
  source.Cells(i, 1).AddComment "n"
 Next i
 If copy Then
  source.Copy After:=source
  Set copied = Worksheets(2)
 End If
 extra.Range("D2").AddComment "other"
 source.Cells(count + 1, 1).AddComment "later"
 If copy Then copied.Cells(count + 1, 1).AddComment "later"
 Notes = CStr(source.Cells(count + 1, 1).Comment.Shape.ID) & "|" & CStr(extra.Range("D2").Comment.Shape.ID)
 If copy Then Notes = Notes & "|" & CStr(copied.Cells(count + 1, 1).Comment.Shape.ID)
End Function
"#).unwrap();
        // Native v9: the 1024th note can start a continuation at offset zero.
        // An intervening sheet owns its block, so neither source nor copy can
        // simply increment into that sheet's IDs.
        for (count, copy, expected) in [
            (1023, false, "3072|2049"), (1024, false, "2049|3073"),
            (1025, false, "2050|3073"), (1023, true, "4096|3073|5120"),
            (1024, true, "2049|5121|4097"), (1025, true, "2050|5121|4098"),
        ] {
            let mut book = oxicells_core::parse_xlsx(bytes).unwrap();
            {
                let mut host = WorkbookHost::new(&mut book, 0).unwrap();
                assert_eq!(execute_with_host(&module, "Notes", vec![Value::Integer(count), Value::Boolean(copy)], &mut host).unwrap(), Value::String(expected.into()), "count={count}, copy={copy}");
                host.sync_legacy_notes_for_save();
            }
            let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
            editor.apply_workbook(&book).unwrap();
            let saved = editor.save().unwrap();
            let reopened = oxicells_core::parse_xlsx(&saved).unwrap();
            for (before, after) in book.sheets.iter().zip(&reopened.sheets) {
                assert_eq!(before.drawing_id_blocks, after.drawing_id_blocks);
                assert_eq!(before.comments.iter().map(|note| (note.cell, note.shape_id)).collect::<Vec<_>>(), after.comments.iter().map(|note| (note.cell, note.shape_id)).collect::<Vec<_>>());
            }
            let mut no_edit = oxicells_core::XlsxEditor::new(&saved).unwrap();
            no_edit.apply_workbook(&reopened).unwrap();
            assert_eq!(no_edit.save().unwrap(), saved);
        }
    }

    #[test]
    fn worksheet_shape_generated_note_aliases_are_scoped_and_session_local() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/cell_width.xlsm");
        let module = parse_module(r#"Public Function Seed() As String
 Dim ws As Worksheet, other As Worksheet, box As Shape
 Set ws = Worksheets(1)
 ws.Range("A1").AddComment "first"
 ws.Range("B2").AddComment "second"
 ws.Range("B2").Comment.Shape.Name = "Memo"
 ws.Range("E5").AddComment "third"
 ws.Range("E5").Comment.Shape.Name = "Third"
 ws.Range("A1").Comment.Delete
 Set box = ws.Shapes.AddShape(1, 1, 1, 10, 10)
 box.Name = "Box"
 Set other = Worksheets.Add(After:=ws)
 other.Name = "Extra"
 other.Range("D4").AddComment "other"
 Seed = "ready"
End Function
Public Function Attempt(ByVal named As String) As String
 Worksheets(1).Range("B2").Comment.Shape.Name = "Memo"
 On Error Resume Next
 Worksheets(1).Range("B2").Comment.Shape.Name = named
 Attempt = CStr(Err.Number) & "|" & Worksheets(1).Range("B2").Comment.Shape.Name
End Function
Public Function Lookup(ByVal sheet As Long, ByVal key As String, ByVal charts As Boolean) As String
 Dim item As Object, number As Long
 On Error Resume Next
 If charts Then
  Set item = Worksheets(sheet).ChartObjects.Item(key)
 Else
  Set item = Worksheets(sheet).Shapes.Item(key)
 End If
 number = Err.Number
 Err.Clear
 Lookup = CStr(number)
 If Not item Is Nothing Then Lookup = Lookup & "|" & item.Name & "@" & CStr(item.ID)
End Function
Public Function ShiftAndEmpty() As String
 Worksheets.Add Before:=Worksheets(1)
 Worksheets(2).Range("B2:E5").ClearComments
 Worksheets(2).Shapes("Box").Delete
 ShiftAndEmpty = CStr(Worksheets(2).Shapes.Count)
End Function
"#).unwrap();
        let mut book = oxicells_core::parse_xlsx(bytes).unwrap();
        {
            let mut host = WorkbookHost::new(&mut book, 0).unwrap();
            assert_eq!(execute_with_host(&module, "Seed", vec![], &mut host).unwrap(), Value::String("ready".into()));
            // Native14-22: aliases are decimal prefixes, not numeric expressions.
            // Deleted aliases still reject writes; own aliases ignore writes.
            for (name, expected) in [
                ("Comment 1", "70|Memo"), ("comment 01", "70|Memo"),
                ("Comment +1", "70|Memo"), ("Comment 1.5", "70|Memo"),
                ("Comment 1x", "70|Memo"), ("Comment \u{0661}", "70|Memo"),
                ("Comment \u{ff11}", "70|Memo"), ("Comment 2", "0|Memo"),
                ("Comment 3", "70|Memo"), ("Comment 0", "0|Comment 0"),
                ("Comment 4", "0|Comment 4"), ("Comment1", "0|Comment1"),
                ("Comment &H1", "0|Comment &H1"), ("Memo", "0|Memo"),
            ] {
                assert_eq!(execute_with_host(&module, "Attempt", vec![Value::String(name.into())], &mut host).unwrap(), Value::String(expected.into()), "{name}");
            }
            for (key, charts, expected) in [
                ("Comment 1", false, "-2147024882"), ("Comment 01", false, "-2147024882"),
                ("Comment 2", false, "0|Memo@1026"), ("Comment 3", false, "0|Third@1027"),
                ("Memo", false, "0|Memo@1026"), ("Box", false, "0|Box@2"),
                ("Comment 2", true, "-2147024809"), ("Box", true, "-2147024809"),
            ] {
                assert_eq!(execute_with_host(&module, "Lookup", vec![Value::Integer(1), Value::String(key.into()), Value::Boolean(charts)], &mut host).unwrap(), Value::String(expected.into()), "{key}, charts={charts}");
            }
            assert_eq!(execute_with_host(&module, "ShiftAndEmpty", vec![], &mut host).unwrap(), Value::String("0".into()));
            for (sheet, expected) in [(1, "-2147024809"), (2, "-2147024882"), (3, "0|Comment 1@2049")] {
                assert_eq!(execute_with_host(&module, "Lookup", vec![Value::Integer(sheet), Value::String("Comment 1".into()), Value::Boolean(false)], &mut host).unwrap(), Value::String(expected.into()));
            }
            host.sync_legacy_notes_for_save();
        }
        let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
        editor.apply_workbook(&book).unwrap();
        let saved = editor.save().unwrap();
        let mut reopened = oxicells_core::parse_xlsx(&saved).unwrap();
        {
            let mut host = WorkbookHost::new(&mut reopened, 0).unwrap();
            assert_eq!(execute_with_host(&module, "Lookup", vec![Value::Integer(2), Value::String("Comment 1".into()), Value::Boolean(false)], &mut host).unwrap(), Value::String("-2147024809".into()));
        }
        let mut unchanged = oxicells_core::XlsxEditor::new(&saved).unwrap();
        unchanged.apply_workbook(&reopened).unwrap();
        assert_eq!(unchanged.save().unwrap(), saved);
    }

    #[test]
    fn worksheet_shape_ranges_keep_native_order_subset_and_deleted_item_errors() {
        let module = parse_module(r#"Private Function ItemError(ByVal selected As ShapeRange, ByVal key As Variant) As Long
 Dim item As Shape
 On Error Resume Next
 Set item = selected.Item(key)
 ItemError = Err.Number
End Function
Private Function CountError(ByVal selected As ShapeRange) As Long
 Dim count As Long
 On Error Resume Next
 count = selected.Count
 CountError = Err.Number
End Function
Public Function Mixed() As String
 Dim box As Shape, selected As ShapeRange
 Set box = Worksheets(1).Shapes.AddShape(1, 1, 1, 10, 10)
 box.Name = "Box"
 Worksheets(1).Range("A1").AddComment "first"
 Worksheets(1).Range("B2").AddComment "second"
 Worksheets(1).Range("B2").Comment.Shape.Name = "Memo"
 Set selected = Worksheets(1).Shapes.Range(Array("Memo", "Box"))
 Mixed = CStr(selected.Count) & "|" & selected.Item(1).Name & "|" & selected.Item("Comment 2").Name & "|" & CStr(ItemError(selected, "Comment 1"))
 Worksheets(1).Range("B2").Comment.Delete
 Mixed = Mixed & "|" & CStr(selected.Count) & "|" & CStr(ItemError(selected, "Memo"))
 box.Delete
 Mixed = Mixed & "|" & CStr(CountError(selected)) & "|" & CStr(ItemError(selected, "Box"))
End Function
Public Function Ordinary() As String
 Dim box As Shape, selected As ShapeRange
 Set box = Worksheets(1).Shapes.AddShape(1, 1, 1, 10, 10)
 box.Name = "Box"
 Set selected = Worksheets(1).Shapes.Range(Array("Box"))
 Ordinary = CStr(ItemError(selected, "missing")) & "|" & CStr(ItemError(selected, 0)) & "|" & CStr(ItemError(selected, 2))
 box.Delete
 Ordinary = Ordinary & "|" & CStr(CountError(selected)) & "|" & CStr(ItemError(selected, 1)) & "|" & CStr(ItemError(selected, "missing")) & "|" & CStr(ItemError(selected, 2))
End Function
Public Function NotesOnly() As String
 Dim selected As ShapeRange
 Worksheets(1).Range("A1").AddComment "first"
 Worksheets(1).Range("A1").Comment.Shape.Name = "Memo"
 Worksheets(1).Range("B2").AddComment "second"
 Worksheets(1).Range("B2").Comment.Shape.Name = "Third"
 Set selected = Worksheets(1).Shapes.Range(Array("Third", "Memo"))
 NotesOnly = CStr(selected.Count) & "|" & selected.Item(1).Name & "|" & selected.Item(2).Name
 Worksheets(1).Range("A1").Comment.Shape.Delete
 NotesOnly = NotesOnly & "|" & CStr(selected.Count)
 Worksheets(1).Range("B2").Comment.Shape.Delete
 NotesOnly = NotesOnly & "|" & CStr(selected.Count) & "|" & CStr(ItemError(selected, 0)) & "|" & CStr(ItemError(selected, 1))
End Function
Public Function CallerOrder() As String
 Dim box As Shape, other As Shape, selected As ShapeRange
 Set box = Worksheets(1).Shapes.AddShape(1, 1, 1, 10, 10)
 box.Name = "Box"
 Set other = Worksheets(1).Shapes.AddShape(1, 20, 1, 10, 10)
 other.Name = "Second"
 Worksheets(1).Range("A1").AddComment "first"
 Worksheets(1).Range("A1").Comment.Shape.Name = "Memo"
 Worksheets(1).Range("B2").AddComment "second"
 Worksheets(1).Range("B2").Comment.Shape.Name = "Third"
 Set selected = Worksheets(1).Shapes.Range(Array("Third", "Second", "Memo", "Box"))
 CallerOrder = selected.Item(1).Name & "|" & selected.Item(2).Name & "|" & selected.Item(3).Name & "|" & selected.Item(4).Name
End Function
Public Function MixedOrdinaryDeleted() As String
 Dim box As Shape, selected As ShapeRange
 Set box = Worksheets(1).Shapes.AddShape(1, 1, 1, 10, 10)
 box.Name = "Box"
 Worksheets(1).Range("A1").AddComment "first"
 Worksheets(1).Range("A1").Comment.Shape.Name = "Memo"
 Set selected = Worksheets(1).Shapes.Range(Array("Box", "Memo"))
 box.Delete
 MixedOrdinaryDeleted = CStr(CountError(selected)) & "|" & CStr(ItemError(selected, 1)) & "|" & selected.Item("Memo").Name
 Worksheets(1).Range("A1").Comment.Shape.Delete
 MixedOrdinaryDeleted = MixedOrdinaryDeleted & "|" & CStr(CountError(selected))
End Function
Public Function DuplicateCount(ByVal mode As Long) As String
 Dim box As Shape, other As Shape, selected As ShapeRange
 Set box = Worksheets(1).Shapes.AddShape(1, 1, 1, 10, 10)
 box.Name = "Box"
 Set other = Worksheets(1).Shapes.AddShape(1, 20, 1, 10, 10)
 other.Name = "Second"
 Select Case mode
  Case 0: Set selected = Worksheets(1).Shapes.Range(Array("Box", "Box"))
  Case 1: Set selected = Worksheets(1).Shapes.Range(Array("Box", "Box", "Box"))
  Case 2: Set selected = Worksheets(1).Shapes.Range(Array("Box", "Box", "Second", "Second"))
  Case 3: Set selected = Worksheets(1).Shapes.Range(Array("Box", "Box", "Box", "Second", "Second", "Second"))
 End Select
 DuplicateCount = CStr(CountError(selected)) & "|" & selected.Item(1).Name & "|" & selected.Item(2).Name
 If mode = 1 Or mode = 3 Then DuplicateCount = DuplicateCount & "|" & CStr(selected.Count)
End Function
Public Function EmptySelection() As String
 Dim selected As ShapeRange
 On Error Resume Next
 Set selected = Worksheets(1).Shapes.Range(Array())
 EmptySelection = CStr(Err.Number)
End Function
Private Function ItemName(ByVal selected As ShapeRange, ByVal key As Variant) As String
 Dim item As Shape
 On Error Resume Next
 Set item = selected.Item(key)
 If Not item Is Nothing Then ItemName = item.Name
End Function
Private Function ItemMessage(ByVal selected As ShapeRange, ByVal key As Variant) As String
 Dim item As Shape
 On Error Resume Next
 Set item = selected.Item(key)
 ItemMessage = CStr(Err.Number) & ":" & Err.Description
End Function
Public Function DeletedSlots(ByVal mode As Long) As String
 Dim box As Shape, other As Shape, selected As ShapeRange
 Set box = Worksheets(1).Shapes.AddShape(1, 1, 1, 10, 10)
 box.Name = "Box"
 Set other = Worksheets(1).Shapes.AddShape(1, 20, 1, 10, 10)
 other.Name = "Other"
 If mode = 0 Then
  Set selected = Worksheets(1).Shapes.Range(Array("Box", "Box", "Other", "Other"))
 Else
  Set selected = Worksheets(1).Shapes.Range(Array("Box", "Box", "Other"))
 End If
 box.Delete
 DeletedSlots = CStr(CountError(selected))
 If mode = 1 Then DeletedSlots = DeletedSlots & ":" & CStr(selected.Count)
 DeletedSlots = DeletedSlots & "|" & CStr(ItemError(selected, 1)) & "|" & CStr(ItemError(selected, 2)) & "|" & CStr(ItemError(selected, 3)) & "|" & CStr(ItemError(selected, 4))
 DeletedSlots = DeletedSlots & "|" & CStr(ItemError(selected, "Other")) & "|" & ItemName(selected, "Other")
 If mode = 0 Then DeletedSlots = DeletedSlots & "|" & ItemName(selected, 3)
 other.Delete
 DeletedSlots = DeletedSlots & "|" & CStr(ItemError(selected, 1)) & "|" & CStr(ItemError(selected, 2)) & "|" & CStr(ItemError(selected, 3)) & "|" & CStr(ItemError(selected, 4))
End Function
Public Function History(ByVal mode As Long) As String
 Dim box As Shape, selected As ShapeRange, other As ShapeRange, item As Object
 Set box = Worksheets(1).Shapes.AddShape(1, 1, 1, 10, 10)
 box.Name = "Box"
 Worksheets(1).Range("A1").AddComment "memo"
 Worksheets(1).Range("A1").Comment.Shape.Name = "Memo"
 Set selected = Worksheets(1).Shapes.Range(Array("Box", "Memo"))
 Select Case mode
  Case 1: Set item = selected.Item(1)
  Case 2
   Set other = Worksheets(1).Shapes.Range(Array("Box"))
   Set item = other.Item(1)
  Case 3
   Set item = selected.Item(1)
   Set selected = Worksheets(1).Shapes.Range(Array("Box", "Memo"))
  Case 4
   On Error Resume Next
   Set item = selected.Item("missing")
   Err.Clear
   On Error GoTo 0
  Case 5: Set item = selected.Item(2)
 End Select
 box.Delete
 History = ItemMessage(selected, 0) & "|" & ItemMessage(selected, 1)
End Function
Public Function ScalarProperties() As String
 Dim box As Shape, other As Shape, selected As ShapeRange, ignored As Variant, number As Long
 Set box = Worksheets(1).Shapes.AddShape(1, 10, 10, 20, 15)
 box.Name = "Box"
 Set other = Worksheets(1).Shapes.AddShape(1, 40, 20, 30, 25)
 other.Name = "Other"
 Set selected = Worksheets(1).Shapes.Range(Array("Other", "Box"))
 On Error Resume Next
 ignored = selected.Name
 number = Err.Number
 Err.Clear
 On Error GoTo 0
 ScalarProperties = CStr(number) & "|" & TypeName(selected.Left) & ":" & CStr(selected.Left) & "|" & CStr(selected.Width)
 Worksheets(1).Range("A1").AddComment "memo"
 Worksheets(1).Range("A1").Comment.Shape.Name = "Memo"
 Set selected = Worksheets(1).Shapes.Range(Array("Box", "Memo"))
 On Error Resume Next
 ignored = selected.Left
 number = Err.Number
 Err.Clear
 selected.Name = "Changed"
 ScalarProperties = ScalarProperties & "|" & CStr(number) & "|" & CStr(Err.Number)
 Err.Clear
 On Error GoTo 0
 ScalarProperties = ScalarProperties & "|" & box.Name & "|" & Worksheets(1).Range("A1").Comment.Shape.Name
End Function
Public Function NotePoints() As String
 Dim note As Shape
 Worksheets(1).Range("A1").AddComment "memo"
 Set note = Worksheets(1).Range("A1").Comment.Shape
 NotePoints = CStr(note.Top)
 note.Left = 0.375
 note.Top = 1.125
 note.Width = 0
 note.Height = 80
 NotePoints = NotePoints & "|" & CStr(note.Left) & "|" & CStr(note.Top) & "|" & CStr(note.Width) & "|" & CStr(note.Height)
End Function
"#).unwrap();
        // Native25-34: ranges retain separate ordinary/note backends, caller
        // order within each, and native error behavior after deletion.
        for (procedure, expected) in [
            ("Mixed", "2|Box|Memo|-2147024809|1|-2147024809|424|-2147024809"),
            ("Ordinary", "-2147352565|-2147352565|-2147352565|424|9|9|-2147352565"),
            ("NotesOnly", "2|Third|Memo|1|0|9|-2147024809"),
            ("CallerOrder", "Second|Box|Third|Memo"),
            ("MixedOrdinaryDeleted", "424|424|Memo|424"),
            ("EmptySelection", "1004"),
            ("ScalarProperties", "70|Single:-2.147484E+09|-2.147484E+09|1004|1004|Box|Memo"),
            ("NotePoints", "1.5|0|1.5|0.75|80.25"),
        ] {
            let mut book = workbook();
            {
                let mut host = WorkbookHost::new(&mut book, 0).unwrap();
                assert_eq!(execute_with_host(&module, procedure, vec![], &mut host).unwrap(), Value::String(expected.into()), "{procedure}");
                host.sync_legacy_notes_for_save();
            }
            if matches!(procedure, "NotesOnly" | "MixedOrdinaryDeleted") {
                assert!(book.sheets[0].comments.is_empty(), "Shape.Delete must remove the persisted note");
            }
        }
        for (mode, expected) in [(0, "424|Box|Box"), (1, "0|Box|Box|3"), (2, "424|Box|Box"), (3, "0|Box|Box|6")] {
            let mut book = workbook();
            let mut host = WorkbookHost::new(&mut book, 0).unwrap();
            assert_eq!(execute_with_host(&module, "DuplicateCount", vec![Value::Integer(mode)], &mut host).unwrap(), Value::String(expected.into()), "mode {mode}");
        }
        for (mode, expected) in [
            (0, "424|9|9|0|0|9||Other|9|9|9|9"),
            (1, "0:1|0|-2147352565|-2147352565|-2147352565|0|Other|9|-2147352565|-2147352565|-2147352565"),
        ] {
            let mut book = workbook();
            let mut host = WorkbookHost::new(&mut book, 0).unwrap();
            assert_eq!(execute_with_host(&module, "DeletedSlots", vec![Value::Integer(mode)], &mut host).unwrap(), Value::String(expected.into()), "mode {mode}");
        }
        for mode in 0..6 {
            let mut book = workbook();
            let mut host = WorkbookHost::new(&mut book, 0).unwrap();
            let first = if matches!(mode, 1 | 4) {
                "424:The index into the specified collection is out of bounds."
            } else { "424:Object required" };
            assert_eq!(execute_with_host(&module, "History", vec![Value::Integer(mode)], &mut host).unwrap(), Value::String(format!("{first}|424:Object required")), "mode {mode}");
        }

        let points = parse_module(r#"Private Function PositionText(ByVal box As Shape) As String
 PositionText = CStr(box.Left) & ":" & CStr(box.Width)
End Function
Public Function OrdinaryPoints(ByVal mode As Long) As String
 Dim box As Shape, oldSize As Double, newSize As Double, left As Double
 left = 10
 oldSize = 100
 newSize = 0.75
 If mode = 1 Or mode = 2 Then
  oldSize = 0.75
  newSize = 1
 End If
 If mode = 2 Then left = -0.375
 If mode = 3 Then left = 100000
 Set box = Worksheets(1).Shapes.AddShape(1, left, 10, oldSize, 40)
 OrdinaryPoints = PositionText(box)
 box.Width = newSize
 OrdinaryPoints = OrdinaryPoints & "|" & PositionText(box)
 box.Width = oldSize
 OrdinaryPoints = OrdinaryPoints & "|" & PositionText(box)
End Function
Public Function ChartPrecision() As String
 Dim co As ChartObject
 Set co = Worksheets(1).ChartObjects.Add(10, 10, 0.375, 40)
 ChartPrecision = TypeName(co.Width) & ":" & CStr(co.Width) & "|" & TypeName(co.ShapeRange.Item(1).Width) & ":" & CStr(co.ShapeRange.Item(1).Width)
End Function
Public Function SelectBackend(ByVal kind As Long, ByVal removed As Long) As Long
 Dim box As Shape, selected As ShapeRange
 Set box = Worksheets(1).Shapes.AddShape(1, 10, 10, 20, 20)
 box.Name = "Box"
 Worksheets(1).Range("A1").AddComment "note"
 Worksheets(1).Range("A1").Comment.Shape.Name = "Memo"
 Select Case kind
  Case 0: Set selected = Worksheets(1).Shapes.Range(Array("Box"))
  Case 1: Set selected = Worksheets(1).Shapes.Range(Array("Memo"))
  Case 2: Set selected = Worksheets(1).Shapes.Range(Array("Box", "Memo"))
 End Select
 If removed = 1 Then box.Delete
 If removed = 2 Then Worksheets(1).Range("A1").Comment.Delete
 On Error Resume Next
 selected.Select
 SelectBackend = Err.Number
End Function"#).unwrap();
        for (mode, expected) in [(0, "10:100|10.00008:0.75|10:100"),
            (1, "10:0.75|9.999921:1|10:0.75"),
            (2, "0:0.7500787|0:1|7.874016E-05:0.75"),
            (3, "100000:100|100000:0.75|100000:100")] {
            let mut book = workbook();
            let mut host = WorkbookHost::new(&mut book, 0).unwrap();
            assert_eq!(execute_with_host(&points, "OrdinaryPoints", vec![Value::Integer(mode)], &mut host).unwrap(),
                Value::String(expected.into()), "mode {mode}");
        }
        let mut chart_book = workbook();
        let mut chart_host = WorkbookHost::new(&mut chart_book, 0).unwrap();
        assert_eq!(execute_with_host(&points, "ChartPrecision", vec![], &mut chart_host).unwrap(),
            Value::String("Double:0.375039368867874|Single:0.3750394".into()));
        for (kind, removed, expected) in [(0, 0, 0), (0, 1, 424), (0, 2, 0),
            (1, 0, 70), (1, 1, 70), (1, 2, -2_147_417_848),
            (2, 0, 1004), (2, 1, 1004), (2, 2, 1004)] {
            let mut book = workbook();
            let mut host = WorkbookHost::new(&mut book, 0).unwrap();
            assert_eq!(execute_with_host(&points, "SelectBackend", vec![Value::Integer(kind), Value::Integer(removed)], &mut host).unwrap(),
                Value::Integer(expected), "kind {kind}, removed {removed}");
        }
    }

    #[test]
    fn worksheet_shape_note_copy_preserves_custom_names_and_rebases_defaults() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/cell_width.xlsm");
        let module = parse_module(r#"Public Function Notes(ByVal named As String, ByVal startCustom As Boolean) As String
 Dim source As Worksheet, copied As Worksheet
 Set source = Worksheets(1)
 source.Range("A1").AddComment "first"
 source.Range("B2").AddComment "kept"
 source.Range("A1").Comment.Delete
 If startCustom Then source.Range("B2").Comment.Shape.Name = "Memo"
 If Len(named) > 0 Then source.Range("B2").Comment.Shape.Name = named
 source.Copy After:=source
 Set copied = Worksheets(2)
 source.Range("C3").AddComment "later"
 copied.Range("C3").AddComment "later"
 Notes = source.Range("B2").Comment.Shape.Name & "@" & CStr(source.Range("B2").Comment.Shape.ID) & "|" & copied.Range("B2").Comment.Shape.Name & "@" & CStr(copied.Range("B2").Comment.Shape.ID) & "|" & copied.Range("C3").Comment.Shape.Name & "@" & CStr(copied.Range("C3").Comment.Shape.ID)
End Function
Public Function ReadNames() As String
 ReadNames = Worksheets(1).Range("B2").Comment.Shape.Name & "|" & Worksheets(2).Range("B2").Comment.Shape.Name
End Function
"#).unwrap();
        for (name, start_custom, original, copied) in [
            ("", false, "Comment 2", "Comment 1"), ("Memo", false, "Memo", "Memo"),
            ("Comment 2", false, "Comment 2", "Comment 1"), ("Comment 99", false, "Comment 99", "Comment 99"),
            ("Comment 2", true, "Memo", "Memo"), ("comment 2", true, "Memo", "Memo"),
            ("A B_x0041_&日", true, "A B_x0041_&日", "A B_x0041_&日"), ("9 note", true, "9 note", "9 note"),
            ("Face 😀", true, "Face 😀", "Face 😀"), ("_x0041_", true, "_x0041_", "_x0041_"),
            ("a:b", true, "a:b", "a:b"), ("\u{0301}a", true, "\u{0301}a", "\u{0301}a"),
        ] {
            let mut book = oxicells_core::parse_xlsx(bytes).unwrap();
            {
                let mut host = WorkbookHost::new(&mut book, 0).unwrap();
                assert_eq!(execute_with_host(&module, "Notes", vec![Value::String(name.into()), Value::Boolean(start_custom)], &mut host).unwrap(), Value::String(format!("{original}@1026|{copied}@2049|Comment 2@2050")));
                host.sync_legacy_notes_for_save();
            }
            let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
            editor.apply_workbook(&book).unwrap();
            let saved = editor.save().unwrap();
            let mut reopened = oxicells_core::parse_xlsx(&saved).unwrap();
            {
                let mut host = WorkbookHost::new(&mut reopened, 0).unwrap();
                assert_eq!(execute_with_host(&module, "ReadNames", vec![], &mut host).unwrap(), Value::String(format!("{original}|{copied}")));
            }
            let mut no_edit = oxicells_core::XlsxEditor::new(&saved).unwrap();
            no_edit.apply_workbook(&reopened).unwrap();
            assert_eq!(no_edit.save().unwrap(), saved);
        }
    }

    #[test]
    fn worksheet_copy_group_and_comment_references_belong_to_the_copy() {
        let mut book = workbook();
        let module = parse_module(r#"Public Function CopyGroup() As String
 Dim a As Shape, b As Shape, grouped As Shape
 Set a = Worksheets(1).Shapes.AddShape(1, 10, 10, 20, 20)
 Set b = Worksheets(1).Shapes.AddShape(1, 40, 10, 20, 20)
 Set grouped = Worksheets(1).Shapes.Range(Array(a.Name, b.Name)).Group
 grouped.Name = "Bundle"
 Worksheets(1).Range("A1").AddComment "source"
 Worksheets(1).Copy After:=Worksheets(1)
 Worksheets(2).Shapes("Bundle").Left = 30
 CopyGroup = CStr(Worksheets(1).Shapes("Bundle").GroupItems(1).Left) & "|" & CStr(Worksheets(2).Shapes("Bundle").GroupItems(1).Left)
End Function
"#).unwrap();
        let mut host = WorkbookHost::new(&mut book, 0).unwrap();
        assert_eq!(execute_with_host(&module, "CopyGroup", vec![], &mut host).unwrap(), Value::String("10|30".into()));
        for shape in host.shapes.iter().filter(|shape| shape.sheet == 1) {
            if let Some(parent) = shape.group_parent_id { assert_eq!(host.shape(parent).unwrap().sheet, 1); }
            for child in &shape.group_children { assert_eq!(host.shape(*child).unwrap().sheet, 1); }
            if let Some(at) = shape.comment_at { assert_eq!(at.sheet, 1); }
        }
        assert_eq!(host.workbook.sheets[0].drawings[0].from.col_off, 127_000);
        assert_eq!(host.workbook.sheets[1].drawings[0].from.col_off, 381_000);
    }

    #[test]
    fn worksheet_copy_preserves_and_saves_lossless_headers_independently() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/cell_width.xlsm");
        let module = parse_module(r#"Public Sub CopyHeader(ByVal text As String)
 Worksheets(1).PageSetup.CenterHeader = text
 Worksheets(1).Copy After:=Worksheets(1)
 Worksheets(2).PageSetup.RightFooter = "copy-footer"
End Sub
"#).unwrap();
        for units in ["KEEP".encode_utf16().collect::<Vec<_>>(), vec![0x41, 0xd800, 0x42],
            "_x0041_\n&Lleft".encode_utf16().collect::<Vec<_>>()]
        {
            let mut book = oxicells_core::parse_xlsx(bytes).unwrap();
            book.sheets[0].header_footer = Some(oxicells_core::ir::HeaderFooter {
                odd_footer: "&CSOURCE-FOOT".encode_utf16().collect(),
                even_header: "&CEVEN".encode_utf16().collect(),
                first_footer: "&CFIRST".encode_utf16().collect(),
                different_first: true, different_odd_even: true,
                scale_with_doc: false, align_with_margins: false, ..Default::default()
            });
            {
                let mut host = WorkbookHost::new(&mut book, 0).unwrap();
                execute_with_host(&module, "CopyHeader", vec![Value::from_utf16(units)], &mut host).unwrap();
            }
            let expected: Vec<_> = book.sheets.iter().map(|sheet| sheet.header_footer.clone()).collect();
            assert_eq!(expected.len(), 2);
            assert_eq!(expected[0].as_ref().unwrap().odd_sections()[4], "SOURCE-FOOT".encode_utf16().collect::<Vec<_>>());
            assert_eq!(expected[0].as_ref().unwrap().odd_sections()[5], Vec::<u16>::new());
            assert_eq!(expected[1].as_ref().unwrap().odd_sections()[5], "copy-footer".encode_utf16().collect::<Vec<_>>());
            let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
            editor.apply_workbook(&book).unwrap();
            let saved = editor.save().unwrap();
            let reopened = oxicells_core::parse_xlsx(&saved).unwrap();
            assert_eq!(reopened.sheets.iter().map(|sheet| sheet.header_footer.clone()).collect::<Vec<_>>(), expected);
            let mut no_edit = oxicells_core::XlsxEditor::new(&saved).unwrap();
            no_edit.apply_workbook(&reopened).unwrap();
            assert_eq!(no_edit.save().unwrap(), saved);
        }
    }

    #[test]
    fn worksheet_copy_names_continue_native_families_and_report_native_errors() {
        let module = parse_module(r#"Public Function Measure(ByVal sourceName As String, ByVal occupiedName As String) As String
 Dim origin As Worksheet, target As Worksheet, extra As Worksheet, i As Long, text As String
 On Error GoTo Failed
 Set origin = Worksheets(1)
 origin.Name = sourceName
 If Len(occupiedName) > 0 Then
  Set extra = Worksheets.Add(After:=Worksheets(Worksheets.Count))
  extra.Name = occupiedName
 End If
 text = "SOURCE|" & origin.Name
 For i = 1 To 3
  origin.Copy After:=Worksheets(Worksheets.Count)
  Set target = Worksheets(Worksheets.Count)
  text = text & "|COPY|" & target.Name
  Set origin = target
 Next i
 Measure = text
 Exit Function
Failed:
 Measure = text & "|ERROR|" & CStr(Err.Number) & "|" & Err.Description
End Function
"#).unwrap();
        for (name, occupied, expected) in [
            ("Budget", "", "SOURCE|Budget|COPY|Budget (2)|COPY|Budget (3)|COPY|Budget (4)"),
            ("Budget", "Budget (3)", "SOURCE|Budget|COPY|Budget (2)|COPY|Budget (4)|COPY|Budget (5)"),
            ("Budget (8)", "Budget (9)", "SOURCE|Budget (8)|COPY|Budget (10)|COPY|Budget (11)|COPY|Budget (12)"),
            ("Budget(2)", "", "SOURCE|Budget(2)|COPY|Budget(3)|COPY|Budget(4)|COPY|Budget(5)"),
            ("Budget (32767)", "", "SOURCE|Budget (32767)|COPY|Budget (32768)|COPY|Budget (32768) (2)|COPY|Budget (32768) (3)"),
            ("Budget (-2)", "", "SOURCE|Budget (-2)|ERROR|1004|シート名が長すぎます。"),
            ("Budget (٢)", "", "SOURCE|Budget (٢)|COPY|Budget (3)|COPY|Budget (4)|COPY|Budget (5)"),
            ("abcdefghijklmnopqrstuvwxyzABCDE", "", "SOURCE|abcdefghijklmnopqrstuvwxyzABCDE|COPY|abcdefghijklmnopqrstuvwxyzA (2)|COPY|abcdefghijklmnopqrstuvwxyzA (3)|COPY|abcdefghijklmnopqrstuvwxyzA (4)"),
        ] {
            let mut book = workbook();
            let mut host = WorkbookHost::new(&mut book, 0).unwrap();
            host.error_language = ErrorLanguage::Japanese;
            let result = execute_with_host(&module, "Measure", vec![Value::String(name.into()), Value::String(occupied.into())], &mut host).unwrap();
            assert_eq!(result, Value::String(expected.into()), "{name}");
            assert_eq!(host.workbook.sheets[0].name, name);
            if !occupied.is_empty() { assert!(host.workbook.sheets.iter().any(|sheet| sheet.name == occupied)); }
        }
    }

    #[test]
    fn worksheet_copy_saves_its_cells_without_editing_the_source() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/cell_width.xlsm");
        let mut book = oxicells_core::parse_xlsx(bytes).unwrap();
        let original_name = book.sheets[0].name.clone();
        let original = serde_json::to_value(&book.sheets[0].rows.iter().find(|row| row.index == 1).unwrap().cells.iter().find(|cell| cell.col == 0).unwrap().value).unwrap();
        let source_id = book.sheets[0].origin_id.unwrap();
        let module = parse_module("Public Sub CopyAndEdit()\nWorksheets(1).Copy After:=Worksheets(1)\nWorksheets(2).Range(\"A1\").Value = \"copy-only\"\nEnd Sub\n").unwrap();
        {
            let mut host = WorkbookHost::new(&mut book, 0).unwrap();
            execute_with_host(&module, "CopyAndEdit", vec![], &mut host).unwrap();
        }
        assert_eq!(book.sheets.len(), 2);
        let copy_id = book.sheets[1].origin_id.unwrap();
        assert_ne!(source_id, copy_id);
        assert_eq!(book.copied_sheet_origins.get(&copy_id), Some(&source_id));
        let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
        editor.apply_workbook(&book).unwrap();
        let saved = editor.save().unwrap();
        let reopened = oxicells_core::parse_xlsx(&saved).unwrap();
        let source = reopened.sheets.iter().find(|sheet| sheet.name == original_name).unwrap();
        let copied = reopened.sheets.iter().find(|sheet| sheet.name != original_name).unwrap();
        assert_eq!(serde_json::to_value(&source.rows.iter().find(|row| row.index == 1).unwrap().cells.iter().find(|cell| cell.col == 0).unwrap().value).unwrap(), original);
        assert!(matches!(&copied.rows.iter().find(|row| row.index == 1).unwrap().cells.iter().find(|cell| cell.col == 0).unwrap().value, CellValue::String(value) if value == "copy-only"));
    }

    #[test]
