    #[test]
    fn legacy_notes_created_edited_and_deleted_survive_normal_save() {
        let bytes = include_bytes!("../../../tests/fixtures/conditional/visual_rules.xlsx");
        let source = "Public Sub CreateNotes()\nRange(\"F2\").AddComment \"first\"\nRange(\"G2\").AddComment \"remove me\"\nEnd Sub\nPublic Sub EditNotes()\nRange(\"F2\").Comment.Text \"changed\"\nRange(\"G2\").Comment.Delete\nEnd Sub\nPublic Function ReadNotes() As String\nReadNotes=Range(\"F2\").Comment.Text & \"|\" & Range(\"A1\").SpecialCells(-4144).Address\nEnd Function";
        let result = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), source, Some("CreateNotes"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(result.error.is_none(), "{:?}", result.error.as_ref().map(|error| &error.message));
        let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
        editor.apply_workbook(&result.workbook).unwrap();
        let first = editor.save().unwrap();
        let changed = execute_workbook_action_in_session(oxicells_core::parse_xlsx(&first).unwrap(), source, Some("EditNotes"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(changed.error.is_none(), "{:?}", changed.error.as_ref().map(|error| &error.message));
        let mut editor = oxicells_core::XlsxEditor::new(&first).unwrap();
        editor.apply_workbook(&changed.workbook).unwrap();
        let second = editor.save().unwrap();
        let read = execute_workbook_action_in_session(oxicells_core::parse_xlsx(&second).unwrap(), source, Some("ReadNotes"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(read.error.is_none(), "{:?}", read.error.as_ref().map(|error| &error.message));
        assert_eq!(serde_json::to_value(&read.result).unwrap(), serde_json::json!({"type":"string", "value":"changed|$F$2"}));
    }

    #[test]
