    #[test]
    fn vba_binds_sparse_named_range_dimensions() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub NamedDimensions()
               Set horizontal = Range(\"B2:C3\").Offset(ColumnOffset:=2).Resize(ColumnSize:=3)
               Set vertical = Range(\"B2:C3\").Offset(RowOffset:=2).Resize(RowSize:=1)
               horizontal.Value = 5
               vertical.Value = 7
               Debug.Print horizontal.Address(False, False), vertical.Address(False, False)
             End Sub\n",
        )
        .unwrap();
        let debug_output = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "NamedDimensions", vec![], &mut host).unwrap();
            host.take_debug_output()
        };

        assert_eq!(debug_output, vec!["D2:F3\tB4:C4".to_string()]);
        assert!(matches!(
            workbook.sheets[0]
                .rows
                .iter()
                .find(|row| row.index == 2)
                .unwrap()
                .cells
                .iter()
                .find(|cell| cell.col == 3)
                .unwrap()
                .value,
            CellValue::Number(5.0)
        ));
        assert!(matches!(
            workbook.sheets[0]
                .rows
                .iter()
                .find(|row| row.index == 4)
                .unwrap()
                .cells
                .iter()
                .find(|cell| cell.col == 1)
                .unwrap()
                .value,
            CellValue::Number(7.0)
        ));
    }

    #[test]
    fn vba_binds_named_cell_copy_address_and_merge_arguments() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub NamedRangeCalls()
               Range(Cell1:=\"A1\").Value = 11
               Set target = Cells(RowIndex:=3, ColumnIndex:=2)
               Range(Cell1:=\"A1\").Copy Destination:=target
               Range(Cell1:=\"D1\", Cell2:=\"E2\").Merge Across:=False
               Range(Cell1:=\"D1:E2\").Borders(Index:=xlEdgeBottom).LineStyle = xlContinuous
               MsgBox Prompt:=\"finished\", Title:=\"Named calls\"
               Debug.Print target.Address(ColumnAbsolute:=False), target.Address(RowAbsolute:=False), target.Value, Range(\"D1:E2\").MergeCells, Range(\"D1:E2\").Borders(xlEdgeBottom).LineStyle
             End Sub\n",
        )
        .unwrap();
        let (debug_output, messages) = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "NamedRangeCalls", vec![], &mut host).unwrap();
            (host.take_debug_output(), host.take_messages())
        };

        assert_eq!(debug_output, vec!["B$3\t$B3\t11\tTrue\t1".to_string()]);
        assert_eq!(messages.len(), 1);
        assert_eq!(messages[0].prompt, "finished");
        assert_eq!(messages[0].title, "Named calls");
    }

