    #[test]
    fn shape_scale_methods_honor_excel_anchor_and_validation() {
        let base = include_bytes!("../../../tests/fixtures/basic_test.xlsx");
        let book = oxicells_core::parse_xlsx(base).unwrap();
        let source = r#"Public Sub ScaleShape()
            Set s = ActiveSheet.Shapes.AddShape(1, 200, 100, 100, 60)
            s.ScaleWidth 2, False, 1
            s.ScaleHeight 2, False, 2
            s.ScaleWidth 0.5, False
            Debug.Print Format(s.Left, "0.0") & "/" & Format(s.Top, "0.0") & "/" & Format(s.Width, "0.0") & "/" & Format(s.Height, "0.0")
            ActiveWorkbook.SaveCopyAs "C:\work\scaled.xlsx"
            s.ScaleWidth -1, False, 0
            Debug.Print Format(s.Width, "0.0")
            On Error Resume Next
            s.ScaleWidth 2, False, 3
            Debug.Print CStr(Err.Number) & "/" & Err.Description
            Err.Clear
            s.ScaleHeight 2, True, 0
            Debug.Print CStr(Err.Number) & "/" & Err.Description
            Debug.Print Format(s.Width, "0.0") & "/" & Format(s.Height, "0.0")
        End Sub"#;
        let mut context = failure_context();
        context.file_context = Some(file_io::FileContext {
            edit_revision: None, source_code_page: None,
            package_bytes: Some(base.to_vec()),
            full_name: Some("C:\\work\\source.xlsx".into()),
            read_only: Some(true),
            folders: vec!["C:\\work".into()],
            files: vec![],
        });
        let mut session = None;
        let outcome = execute_workbook_action_in_session(
            book, source, Some("ScaleShape"), vec![], 0, context, &mut session,
        ).unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        assert_eq!(outcome.debug_output, [
            "150.0/40.0/100.0/120.0", "0.0",
            "-2147024809/指定された値は境界を超えています。",
            "-2147024809/RelativeToOriginalSize 引数は、ピクチャまたは OLE オブジェクトにしか適用できません。",
            "0.0/120.0",
        ]);
        assert_eq!(outcome.files.len(), 1);
        let mut saved = oxicells_core::parse_xlsx(&outcome.files[0].bytes).unwrap();
        let reopened = WorkbookHost::new(&mut saved, 0).unwrap();
        let shape = reopened.shapes.iter().find(|shape| shape.name == "Rectangle 1").unwrap();
        assert!((shape.left - 150.0).abs() < 0.001);
        assert!((shape.top - 40.0).abs() < 0.001);
        assert!((shape.width - 100.0).abs() < 0.001);
        assert!((shape.height - 120.0).abs() < 0.001);
    }

