    #[test]
    fn grouped_shapes_report_each_childs_excel_coordinates() {
        // Excel 16 COM saved this two-shape group with ChildA at 10,10,20,20
        // and ChildB at 40,10,20,20. The drawing anchor stores the group box;
        // each child's frame stores its fraction of that box.
        let bytes = include_bytes!("../../../tests/fixtures/vba/grouped_shapes.xlsx");
        let book = oxicells_core::parse_xlsx(bytes).unwrap();
        assert_eq!(book.sheets[0].drawings.iter().map(|drawing| drawing.group_name.as_deref()).collect::<Vec<_>>(), [Some("MyGroup"), Some("MyGroup")]);
        let source = r#"Public Sub GroupedGeometry()
            Debug.Print ActiveSheet.Shapes.Count & "/" & ActiveSheet.Shapes(1).Name & "/" & ActiveSheet.Shapes(1).Type
            Debug.Print ActiveSheet.Shapes(1).GroupItems.Count
            Debug.Print ActiveSheet.Shapes(1).GroupItems.Item(1).Name
            Debug.Print ActiveSheet.Shapes(1).GroupItems.Item("ChildB").Name
            Debug.Print ActiveSheet.Shapes(1).GroupItems("ChildB").Name
            Debug.Print ActiveSheet.Shapes("ChildA").Name
            Debug.Print ActiveSheet.Shapes("ChildA").ParentGroup.Name
            Debug.Print ActiveSheet.Shapes("ChildA").Left & "/" & ActiveSheet.Shapes("ChildA").Top & "/" & ActiveSheet.Shapes("ChildA").Width & "/" & ActiveSheet.Shapes("ChildA").Height
            Debug.Print ActiveSheet.Shapes("ChildB").Left & "/" & ActiveSheet.Shapes("ChildB").Top & "/" & ActiveSheet.Shapes("ChildB").Width & "/" & ActiveSheet.Shapes("ChildB").Height
        End Sub"#;
        let outcome = execute_workbook_vba(book, source, "GroupedGeometry", vec![], 0, failure_context()).unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        assert_eq!(outcome.debug_output, ["1/MyGroup/6", "2", "ChildA", "ChildB", "ChildB", "ChildA", "MyGroup", "10/10/20/20", "40/10/20/20"]);
    }

