    #[test]
    fn rotated_nested_group_uses_outer_excel_rotation_and_child_geometry() {
        // Excel 16 COM rotates the nested group through its outer group and
        // reports the same effective Rotation on every flattened leaf.
        let bytes = include_bytes!("../../../tests/fixtures/vba/grouped_shapes_nested_rotated.xlsx");
        let book = oxicells_core::parse_xlsx(bytes).unwrap();
        let source = r#"Public Sub RotatedNestedGroup()
            Debug.Print ActiveSheet.Shapes.Count & "/" & ActiveSheet.Shapes(1).Name & "/" & Format(ActiveSheet.Shapes(1).Rotation, "0.000")
            Debug.Print Format(ActiveSheet.Shapes("ChildA").Left, "0.000") & "/" & Format(ActiveSheet.Shapes("ChildA").Top, "0.000") & "/" & Format(ActiveSheet.Shapes("ChildA").Width, "0.000") & "/" & Format(ActiveSheet.Shapes("ChildA").Height, "0.000") & "/" & Format(ActiveSheet.Shapes("ChildA").Rotation, "0.000")
            Debug.Print Format(ActiveSheet.Shapes("ChildB").Left, "0.000") & "/" & Format(ActiveSheet.Shapes("ChildB").Top, "0.000") & "/" & Format(ActiveSheet.Shapes("ChildB").Width, "0.000") & "/" & Format(ActiveSheet.Shapes("ChildB").Height, "0.000") & "/" & Format(ActiveSheet.Shapes("ChildB").Rotation, "0.000")
            Debug.Print Format(ActiveSheet.Shapes("ChildC").Left, "0.000") & "/" & Format(ActiveSheet.Shapes("ChildC").Top, "0.000") & "/" & Format(ActiveSheet.Shapes("ChildC").Width, "0.000") & "/" & Format(ActiveSheet.Shapes("ChildC").Height, "0.000") & "/" & Format(ActiveSheet.Shapes("ChildC").Rotation, "0.000")
        End Sub"#;
        let outcome = execute_workbook_vba(book, source, "RotatedNestedGroup", vec![], 0, failure_context()).unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        assert_eq!(outcome.debug_output, [
            "1/OuterGroup/30.000",
            "14.689/-7.500/20.000/20.000/30.000",
            "40.670/7.500/20.000/20.000/30.000",
            "75.311/27.500/20.000/20.000/30.000",
        ]);
    }

