    #[test]
    fn deleting_group_child_persists_the_ungrouped_survivor() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/grouped_shapes.xlsx");
        let book = oxicells_core::parse_xlsx(bytes).unwrap();
        let mut context = failure_context();
        context.file_context = Some(file_io::FileContext {
            edit_revision: None, source_code_page: None,
            package_bytes: Some(bytes.to_vec()),
            full_name: Some("C:\\work\\grouped.xlsx".into()),
            read_only: Some(true),
            folders: vec!["C:\\work".into()],
            files: vec![],
        });
        let source = r#"Public Sub RemoveGroupChild()
            ActiveSheet.Shapes("MyGroup").GroupItems("ChildA").Delete
            Debug.Print ActiveSheet.Shapes.Count & "/" & ActiveSheet.Shapes(1).Name & "/" & ActiveSheet.Shapes(1).Left
            ActiveWorkbook.SaveCopyAs "C:\work\ungrouped.xlsx"
        End Sub"#;
        let mut session = None;
        let outcome = execute_workbook_action_in_session(
            book, source, Some("RemoveGroupChild"), vec![], 0, context, &mut session,
        ).unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        assert_eq!(outcome.debug_output, ["1/ChildB/40"]);
        assert_eq!(outcome.files.len(), 1);
        if let Some(path) = std::env::var_os("OXI_GROUPED_SHAPE_SAVE_OUTPUT") {
            std::fs::write(path, &outcome.files[0].bytes).unwrap();
        }
        let saved = oxicells_core::parse_xlsx(&outcome.files[0].bytes).unwrap();
        let drawings = &saved.sheets[0].drawings;
        assert_eq!(drawings.len(), 1);
        assert_eq!(drawings[0].name.as_deref(), Some("ChildB"));
        assert!(!drawings[0].grouped);
        assert_eq!(drawings[0].group_name, None);
        assert_eq!(drawings[0].from.col_off, 508_000);
        assert_eq!(drawings[0].to.unwrap().col, 1);
        assert_eq!(drawings[0].to.unwrap().col_off, 152_400);
        let mut archive = zip::ZipArchive::new(std::io::Cursor::new(&outcome.files[0].bytes)).unwrap();
        let mut drawing_xml = String::new();
        std::io::Read::read_to_string(&mut archive.by_name("xl/drawings/drawing1.xml").unwrap(), &mut drawing_xml).unwrap();
        // Native69: the ungrouped survivor keeps its absolute transform.
        assert!(drawing_xml.contains("<a:off x=\"508000\" y=\"127000\"/>"), "{drawing_xml}");
        assert!(drawing_xml.contains("<a:ext cx=\"254000\" cy=\"254000\"/>"), "{drawing_xml}");
    }

