        assert_eq!(saved.sheets[0].drawings.len(), 1);
        assert!(!saved.sheets[0].drawings[0].grouped);
        assert_eq!(saved.sheets[0].drawings[0].from.row, 0);
        assert_eq!(saved.sheets[0].drawings[0].from.row_off, -15_875);
        assert_eq!(saved.sheets[0].drawings[0].to.unwrap().row, 1);
