    #[test]
    fn vba_preserves_module_state_between_entry_point_calls() {
        let mut workbook = workbook();
        let module = parse_module(
            "Private runCount As Long
             Private target As Worksheet
             Public Sub InitializeState()
               Set target = Worksheets(1)
               runCount = 40
             End Sub
             Public Sub ApplyState()
               runCount = runCount + 1
               target.Range(\"A1\").Value = runCount
             End Sub
             Public Function ReadState() As Long
               ReadState = runCount + target.Range(\"A1\").Value
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            let mut runtime = oxivba_core::Runtime::new(&module).with_host(&mut host);
            runtime.call("InitializeState", vec![]).unwrap();
            runtime.call("ApplyState", vec![]).unwrap();
            runtime.call("ApplyState", vec![]).unwrap();
            runtime.call("ReadState", vec![]).unwrap()
        };

        assert_eq!(result, Value::Integer(84));
        assert!(matches!(
            workbook.sheets[0].rows[0].cells[0].value,
            CellValue::Number(42.0)
        ));
    }

    #[test]
    fn vba_tracks_nothing_and_range_object_identity() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function ObjectState() As String
               Dim target As Range
               Dim aliasValue As Object
               ObjectState = (target Is Nothing) & \"|\"
               Set target = Range(\"A1\")
               Set aliasValue = target
               target.Value = 42
               ObjectState = ObjectState & (target Is aliasValue) & \"|\" & (TypeOf target Is Range) & \"|\" & TypeName(target) & \"|\"
               Set aliasValue = Nothing
               ObjectState = ObjectState & (aliasValue Is Nothing) & \"|\" & IsObject(aliasValue) & \"|\"
               On Error Resume Next
               ObjectState = aliasValue.Value
               ObjectState = ObjectState & Err.Number
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "ObjectState", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String("True|True|True|Range|True|True|91".to_string())
        );
        assert!(matches!(
            workbook.sheets[0].rows[0].cells[0].value,
            CellValue::Number(42.0)
        ));
    }

