    #[test]
    fn insertion_inherits_cell_format_like_excel() {
        // Excel 16.0 build 20527: origin 0 copies above/left and origin 1
        // copies below/right, for whole bands and partial cell shifts.
        let source = r#"Public Function InsertFormatProbe(ByVal kind As Long, ByVal origin As Long) As String
Range("A1:C3").Clear
Range("A1").Interior.Color = 255: Range("B1").Interior.Color = 65280
Range("A2").Interior.Color = 16711680: Range("B2").Interior.Color = 65535
If kind = 0 Then Rows(2).Insert xlShiftDown, origin
If kind = 1 Then Columns(2).Insert xlShiftToRight, origin
If kind = 2 Then Range("A2").Insert xlShiftDown, origin
If kind = 3 Then Range("B1").Insert xlShiftToRight, origin
InsertFormatProbe = CStr(Range("A1").Interior.Color) & "|" & CStr(Range("B1").Interior.Color) & "|" & CStr(Range("A2").Interior.Color) & "|" & CStr(Range("B2").Interior.Color) & "|" & CStr(Range("A3").Interior.Color) & "|" & CStr(Range("C1").Interior.Color)
End Function"#;
        for (kind, origin, expected) in [
            (0, 0, "255|65280|255|65280|16711680|16777215"),
            (0, 1, "255|65280|16711680|65535|16711680|16777215"),
            (1, 0, "255|255|16711680|16711680|16777215|65280"),
            (1, 1, "255|65280|16711680|65535|16777215|65280"),
            (2, 0, "255|65280|255|65535|16711680|16777215"),
            (2, 1, "255|65280|16711680|65535|16711680|16777215"),
            (3, 0, "255|255|16711680|65535|16777215|65280"),
            (3, 1, "255|65280|16711680|65535|16777215|65280"),
        ] {
            let book = oxicells_core::parse_xlsx(include_bytes!("../../../tests/fixtures/vba/udf_returned_references.xlsm")).unwrap();
            let mut session = None;
            let result = execute_workbook_action_in_session(book, source, Some("InsertFormatProbe"), vec![Value::Integer(kind), Value::Integer(origin)], 0, failure_context(), &mut session).unwrap();
            assert!(result.error.is_none(), "kind={kind} origin={origin}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "kind={kind} origin={origin}");
        }
    }

    #[test]
    fn intersecting_row_and_column_formats_follow_excel_order_and_survive_save() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/row_height_state.xlsm");
        for (operation, expected) in [
            ("Rows(1).Interior.Color=255: Columns(1).Interior.Color=65280", "65280|255|65280|False|False|False"),
            ("Columns(1).Interior.Color=65280: Rows(1).Interior.Color=255", "255|255|65280|False|False|False"),
            ("Range(\"A1\").Interior.Color=16711680: Rows(1).Interior.Color=255", "255|255|16777215|False|False|False"),
            ("Rows(1).Interior.Color=255: Range(\"A1\").Interior.Color=16711680", "16711680|255|16777215|False|False|False"),
            ("Rows(1).Font.Bold=True: Columns(1).Interior.Color=65280", "65280|16777215|65280|True|True|False"),
            ("Columns(1).Font.Bold=True: Rows(1).Interior.Color=255", "255|255|16777215|True|False|True"),
        ] {
            let source = format!("Public Function MakeCross() As String\nWorksheets.Add\n{operation}\nMakeCross = ReadCross()\nEnd Function\nPublic Function ReadCross() As String\nReadCross = CStr(Range(\"A1\").Interior.Color) & \"|\" & CStr(Range(\"Z1\").Interior.Color) & \"|\" & CStr(Range(\"A100\").Interior.Color) & \"|\" & CStr(Range(\"A1\").Font.Bold) & \"|\" & CStr(Range(\"Z1\").Font.Bold) & \"|\" & CStr(Range(\"A100\").Font.Bold)\nEnd Function");
            let book = oxicells_core::parse_xlsx(bytes).unwrap();
            let mut session = None;
            let result = execute_workbook_action_in_session(book, &source, Some("MakeCross"), vec![], 0, failure_context(), &mut session).unwrap();
            assert!(result.error.is_none(), "{operation}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "runtime {operation}");
            let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
            editor.apply_workbook(&result.workbook).unwrap();
            let reopened = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
            let result = execute_workbook_action_in_session(reopened, &source, Some("ReadCross"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "reopened {operation}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "reopened {operation}");
        }
    }

    #[test]
    fn multi_area_validation_matches_excel_and_survives_save() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/row_height_state.xlsm");
        let source = r#"Public Function MakeMulti() As String
Worksheets.Add
Range("A1:A3,C2:C4").Validation.Add Type:=7, AlertStyle:=1, Operator:=1, Formula1:="=D1"
Range("A1:A3,C2:C4").Validation.IgnoreBlank=False
MakeMulti=ReadMulti()
End Function
Public Function ReadMulti() As String
ReadMulti=CStr(Range("A1:A3,C2:C4").Validation.Type) & "|" & Range("A1:A3,C2:C4").Validation.Formula1 & "|" & One("A1") & "|" & One("A3") & "|" & One("C2") & "|" & One("C4") & "|" & CStr(Range("A1").Validation.IgnoreBlank) & "|" & CStr(Range("C2").Validation.IgnoreBlank) & "|" & Range("A1:A3,C2:C4").Validation.Parent.Address
End Function
Public Function ModifyMulti() As String
Range("A1:A3,C2:C4").Validation.Modify Type:=7, AlertStyle:=1, Operator:=1, Formula1:="=E1"
ModifyMulti=ReadMulti()
End Function
Public Function MakeOverlap() As String
Worksheets.Add
Range("A1:A3,A2:A4").Validation.Add 7,1,1,"=D1"
MakeOverlap=One("A1") & "|" & One("A2") & "|" & One("A3") & "|" & One("A4")
End Function
Public Function MakeAtomic() As String
Worksheets.Add
Range("C2").Validation.Add 7,1,1,"=H1"
On Error Resume Next
Range("A1:A3,C2:C4").Validation.Add 7,1,1,"=D1"
Dim failed As Boolean
failed=(Err.Number<>0): Err.Clear
MakeAtomic=CStr(failed) & "|" & One("A1") & "|" & One("C2")
End Function
Public Function MultiValue() As String
Worksheets.Add
Range("A1,C2").Validation.Add 1,1,5,10
Range("A1").Value2=5: Range("C2").Value2=15
MultiValue=CStr(Range("A1,C2").Validation.Value)
End Function
Public Function One(ByVal address As String) As String
On Error Resume Next
Dim kind As Long
kind=Range(address).Validation.Type
If Err.Number<>0 Then Err.Clear: One="none": Exit Function
One=Range(address).Validation.Formula1
End Function"#;
        let run = |book, procedure| execute_workbook_action_in_session(book, source, Some(procedure), vec![], 0, failure_context(), &mut None).unwrap();
        let mut result = run(oxicells_core::parse_xlsx(bytes).unwrap(), "MakeMulti");
        assert!(result.error.is_none(), "add");
        assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":"7|=D1|=D1|=D3|=F2|=F4|False|False|$A$1:$A$3,$C$2:$C$4"}));
        let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
        editor.apply_workbook(&result.workbook).unwrap();
        let saved = editor.save().unwrap();
        result = run(oxicells_core::parse_xlsx(&saved).unwrap(), "ModifyMulti");
        assert!(result.error.is_none(), "modify");
        assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":"7|=E1|=E1|=E3|=G2|=G4|False|False|$A$1:$A$3,$C$2:$C$4"}));
        let mut editor = oxicells_core::XlsxEditor::new(&saved).unwrap();
        editor.apply_workbook(&result.workbook).unwrap();
        result = run(oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap(), "ReadMulti");
        assert!(result.error.is_none(), "reopen modified");
        assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":"7|=E1|=E1|=E3|=G2|=G4|False|False|$A$1:$A$3,$C$2:$C$4"}));
        for (procedure, expected) in [("MakeOverlap", "=D1|none|none|=D4"), ("MakeAtomic", "True|none|=H1"), ("MultiValue", "False")] {
            let result = run(oxicells_core::parse_xlsx(bytes).unwrap(), procedure);
            assert!(result.error.is_none(), "{procedure}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "{procedure}");
        }
    }

