    #[test]
    fn insertion_inherits_row_and_column_templates_like_excel() {
        // Excel 20527 also copies formats from an otherwise empty row or
        // column; whole bands must keep formatting for cells not yet created.
        let source = r#"Public Function InsertTemplateProbe(ByVal kind As Long) As String
If kind = 0 Or kind = 2 Then Rows(1).Interior.Color = 255 Else Columns(1).Interior.Color = 255
If kind = 0 Then Rows(2).Insert
If kind = 1 Then Columns(2).Insert
If kind = 2 Then Range("A2:C2").Insert xlShiftDown
If kind = 3 Then Range("B1:B3").Insert xlShiftToRight
InsertTemplateProbe = CStr(Range("A2").Interior.Color) & "|" & CStr(Range("B2").Interior.Color) & "|" & CStr(Range("C2").Interior.Color) & "|" & CStr(Range("Z2").Interior.Color) & "|" & CStr(Range("B100").Interior.Color)
End Function"#;
        for (kind, expected) in [(0, "255|255|255|255|16777215"), (1, "255|255|16777215|16777215|255"), (2, "255|255|255|16777215|16777215"), (3, "255|255|16777215|16777215|16777215")] {
            let book = oxicells_core::parse_xlsx(include_bytes!("../../../tests/fixtures/vba/udf_returned_references.xlsm")).unwrap();
            let mut session = None;
            let result = execute_workbook_action_in_session(book, source, Some("InsertTemplateProbe"), vec![Value::Integer(kind)], 0, failure_context(), &mut session).unwrap();
            assert!(result.error.is_none(), "kind={kind}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "kind={kind}");
        }
    }

