    #[test]
    fn column_shift_preserves_column_widths_like_excel() {
        // Excel 16.0 build 20527: entire-column shifts carry width and
        // visibility; cell-only shifts leave the column properties alone.
        let source = r#"Public Function ColumnShiftWidth(ByVal mode As Long) As String
Columns(1).ColumnWidth = 12: Columns(2).ColumnWidth = 20: Columns(3).ColumnWidth = 30
Range("B1").Value2 = 11: Range("C1").Value2 = 22
If mode = 0 Then Columns(2).Insert
If mode = 1 Then Columns(2).Delete
If mode = 2 Then Range("B1").Insert xlShiftToRight
If mode = 3 Then Range("B1").Delete xlShiftToLeft
If mode = 4 Then Columns(1).Insert
If mode = 5 Then Columns(1).Hidden = True: Columns(2).Insert
If mode = 6 Then Columns(3).Hidden = True: Columns(2).Delete
If mode = 7 Then Range("B:C").EntireColumn.Insert
If mode = 8 Then Columns(2).Insert xlShiftToRight, 1
If mode = 9 Then Columns(2).Hidden = True: Columns(2).Insert xlShiftToRight, 1
ColumnShiftWidth = CStr(Columns(1).ColumnWidth) & "|" & CStr(Columns(2).ColumnWidth) & "|" & CStr(Columns(3).ColumnWidth) & "|" & CStr(Columns(4).ColumnWidth)
End Function"#;
        for (mode, expected) in [(0, "12|12|20|30"), (1, "12|30|8.43|8.43"), (2, "12|20|30|8.43"), (3, "12|20|30|8.43"), (4, "8.43|12|20|30"), (5, "0|12|20|30"), (6, "12|0|8.43|8.43"), (7, "12|12|12|20"), (8, "12|20|20|30"), (9, "12|20|0|30")] {
            let book = oxicells_core::parse_xlsx(include_bytes!("../../../tests/fixtures/vba/udf_returned_references.xlsm")).unwrap();
            let mut session = None;
            let result = execute_workbook_action_in_session(book, source, Some("ColumnShiftWidth"), vec![Value::Integer(mode)], 0, failure_context(), &mut session).unwrap();
            assert!(result.error.is_none(), "mode={mode}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "mode={mode}");
        }
    }

