    #[test]
    fn saved_sheet_protection_reaches_fresh_vba_hosts() {
        use std::io::{Cursor, Read, Write};
        let original = include_bytes!("../../../tests/fixtures/vba/array_argument_rank.xlsm");
        for protection in [
            "<sheetProtection sheet=\"1\" formatCells=\"0\"/>",
            "<sheetProtection sheet=\"1\" formatCells=\"0\"></sheetProtection>",
        ] {
            let mut source = zip::ZipArchive::new(Cursor::new(original)).unwrap();
            let mut target = zip::ZipWriter::new(Cursor::new(Vec::new()));
            for index in 0..source.len() {
                let mut part = source.by_index(index).unwrap();
                let name = part.name().to_string();
                let mut bytes = Vec::new();
                part.read_to_end(&mut bytes).unwrap();
                if name == "xl/worksheets/sheet1.xml" {
                    let text = String::from_utf8(bytes).unwrap();
                    assert!(!text.contains("<sheetProtection"));
                    bytes = text.replace("</sheetData>", &format!("</sheetData>{protection}")).into_bytes();
                }
                target.start_file(name, zip::write::SimpleFileOptions::default()).unwrap();
                target.write_all(&bytes).unwrap();
            }
            let bytes = target.finish().unwrap().into_inner();
            let mut book = oxicells_core::parse_xlsx(&bytes).unwrap();
            let module = parse_module(
                "Public Function FormatCell() As String\n\
                 Range(\"A1\").Font.Bold = True\n\
                 FormatCell = CStr(ActiveSheet.ProtectContents) & \"|\" & \
                 CStr(ActiveSheet.Protection.AllowFormattingCells) & \"|\" & \
                 CStr(ActiveSheet.Protection.AllowFormattingRows)\nEnd Function\n\
                 Public Function FitRow() As Long\nOn Error Resume Next\n\
                 Rows(1).AutoFit\nFitRow = Err.Number\nEnd Function\n\
                 Public Function DropProtection() As Boolean\nActiveSheet.Unprotect\n\
                 DropProtection = ActiveSheet.ProtectContents\nEnd Function\n"
            ).unwrap();
            {
                let mut host = WorkbookHost::new(&mut book, 0).unwrap();
                assert_eq!(execute_with_host(&module, "FormatCell", vec![], &mut host).unwrap(),
                    Value::String("True|True|False".to_string()));
            }
            let mut book: Workbook = serde_json::from_slice(&serde_json::to_vec(&book).unwrap()).unwrap();
            {
                let mut host = WorkbookHost::new(&mut book, 0).unwrap();
                assert_eq!(execute_with_host(&module, "FitRow", vec![], &mut host).unwrap(),
                    Value::Integer(1004));
                assert_eq!(execute_with_host(&module, "DropProtection", vec![], &mut host).unwrap(),
                    Value::Boolean(false));
            }
            let mut host = WorkbookHost::new(&mut book, 0).unwrap();
            assert_eq!(execute_with_host(&module, "DropProtection", vec![], &mut host).unwrap(),
                Value::Boolean(false));
        }
    }

    /// What a filter counts as a match.
    ///
    /// Every answer was asked of Excel about a column holding 10, "apple", a
    /// blank, 30, "Apricot", "banana" and 10 under a heading. Note `<>10`,
    /// which keeps the BLANK row, and that text is matched without regard to
    /// case.
    #[test]
    fn vba_filters_the_rows_a_criterion_names() {
        let showing = |criteria: &str| {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Function Showing() As String
                   Range(\"A1\").Value = \"head\"
                   Range(\"A2\").Value = 10
                   Range(\"A3\").Value = \"apple\"
                   Range(\"A5\").Value = 30
                   Range(\"A6\").Value = \"Apricot\"
                   Range(\"A7\").Value = \"banana\"
                   Range(\"A8\").Value = 10
                   Range(\"A1:A8\").AutoFilter {criteria}
                   Dim seen, row
                   seen = \"\"
                   For row = 2 To 8
                     If Not Rows(row).Hidden Then seen = seen & row & \",\"
                   Next row
                   Showing = seen
                 End Function\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            match execute_with_host(&module, "Showing", vec![], &mut host) {
                Ok(Value::String(seen)) => seen,
                Ok(other) => format!("{other:?}"),
                Err(error) => format!("! {error}"),
            }
        };

        assert_eq!(showing("1, \"10\""), "2,8,");
        assert_eq!(showing("1, \">10\""), "5,");
        assert_eq!(showing("1, \">=10\""), "2,5,8,");
        // A blank is not 10 either, so it stays.
        assert_eq!(showing("1, \"<>10\""), "3,4,5,6,7,");
        assert_eq!(showing("1, \"=\""), "4,");
        assert_eq!(showing("1, \"<>\""), "2,3,5,6,7,8,");
        assert_eq!(showing("1, \"apple\""), "3,");
        assert_eq!(showing("1, \"APPLE\""), "3,");
        assert_eq!(showing("1, \"a*\""), "3,6,");
        assert_eq!(showing("1, \"10\", xlOr, \"30\""), "2,5,8,");
        assert_eq!(showing("1, \">=10\", xlAnd, \"<=20\""), "2,8,");
        assert_eq!(showing(""), "2,3,4,5,6,7,8,");
        // A list of values keeps a row holding any of them.
        assert_eq!(showing("1, Array(\"10\", \"banana\"), xlFilterValues"), "2,7,8,");
    }

    /// Whether the first line of a range reads as a heading.
    ///
    /// Every answer was asked of Excel with `Header:=xlGuess`. A first row
    /// that differs from the one under it stays where it is: text over
    /// numbers, or a row that is bold, filled, larger or underlined where the
    /// rest is plain. A row like the ones below it is sorted with them, and an
    /// EMPTY first row is not a heading at all.
    #[test]
    fn vba_guesses_whether_the_first_row_is_a_heading() {
        let sorted = |fill: &str| {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Function Sorted() As String
                   {fill}
                   Range(\"A1:A4\").Sort Key1:=Range(\"A1\"), Order1:=xlAscending, \
                     Header:=xlGuess
                   Dim seen, row
                   seen = \"\"
                   For row = 1 To 4
                     seen = seen & Range(\"A\" & row).Value & \",\"
                   Next row
                   Sorted = seen
                 End Function\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            match execute_with_host(&module, "Sorted", vec![], &mut host) {
                Ok(Value::String(seen)) => seen,
                Ok(other) => format!("{other:?}"),
                Err(error) => format!("! {error}"),
            }
        };
        let numbers = "Range(\"A1\").Value = 99
                       Range(\"A2\").Value = 30
                       Range(\"A3\").Value = 10
                       Range(\"A4\").Value = 20";
        let words = "Range(\"A1\").Value = \"zebra\"
                     Range(\"A2\").Value = \"cherry\"
                     Range(\"A3\").Value = \"apple\"
                     Range(\"A4\").Value = \"banana\"";

        // Alike, so the first row is sorted with the rest.
        assert_eq!(sorted(numbers), "10,20,30,99,");
        assert_eq!(sorted(words), "apple,banana,cherry,zebra,");
        // Text over numbers is a heading.
        assert_eq!(
            sorted(
                "Range(\"A1\").Value = \"head\"
                 Range(\"A2\").Value = 30
                 Range(\"A3\").Value = 10
                 Range(\"A4\").Value = 20"
            ),
            "head,10,20,30,"
        );
        // So is any difference in the dress.
        for dressed in [
            "Range(\"A1\").Font.Bold = True",
            "Range(\"A1\").Interior.Color = 255",
            "Range(\"A1\").Font.Size = 16",
            "Range(\"A1\").Font.Underline = xlUnderlineStyleSingle",
        ] {
            assert_eq!(
                sorted(&format!("{numbers}\n{dressed}")),
                "99,10,20,30,",
                "with {dressed}"
            );
            assert_eq!(
                sorted(&format!("{words}\n{dressed}")),
                "zebra,apple,banana,cherry,",
                "with {dressed}"
            );
        }
        // An empty first row is not a heading.
        assert_eq!(
            sorted(
                "Range(\"A2\").Value = 30
                 Range(\"A3\").Value = 10
                 Range(\"A4\").Value = 20"
            ),
            "10,20,30,,"
        );
    }

    /// Excel 16.0 Japanese Find keeps wide and narrow forms distinct.
    ///
    /// Measured through Excel 16.0 COM (LCID 1041): Find("ABC") skips a cell
    /// holding fullwidth ＡＢＣ and returns the next ASCII match; MatchByte
    /// True gives the same result. Halfwidth and fullwidth kana behave likewise.
    #[test]
    fn vba_reads_a_wide_letter_and_a_narrow_one_as_one() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Found() As String
               Range(\"A1\").Value = \"ＡＢＣ\"
               Range(\"A2\").Value = \"ABC\"
               Range(\"A3\").Value = \"アイ\"
               Range(\"A4\").Value = \"ｱｲ\"\n\
               Range(\"A5\").Value = \"ガ\"\n\
               Range(\"A6\").Value = \"ABC\"
               Found = Range(\"A1:A6\").Find(\"ABC\", Range(\"A6\")).Address(False, False) & \"|\" & _
                 Range(\"A1:A6\").Find(\"ABC\", Range(\"A6\"), , , , , , True).Address(False, False) & \"|\" & _
                 Range(\"A1:A6\").Find(\"ｱｲ\", Range(\"A6\")).Address(False, False) & \"|\" & _\n\
                 Range(\"A1:A6\").Find(\"ｱｲ\", Range(\"A6\"), , , , , , True).Address(False, False) & \"|\" & _\n\
                 Range(\"A1:A6\").Find(\"ABC\", Range(\"A6\")).Address(False, False)
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Found", vec![], &mut host).unwrap()
        };

        assert_eq!(result, Value::String("A2|A2|A4|A4|A2".to_string()));
    }

    /// Hiding a sheet, and the one sheet that cannot be hidden.
    ///
    /// Asked of Excel: a fresh sheet answers -1, `Visible = False` leaves 0,
    /// 2 is the hidden-and-not-offered state, 1 is read as True, 3 is refused,
    /// and hiding the last sheet still showing raises. A hidden sheet's cells
    /// still answer.
    #[test]
    fn vba_hides_a_sheet_but_not_the_last_one_showing() {
        let mut workbook = workbook();
        for name in ["Sheet2", "Sheet3"] {
            let mut another = workbook.sheets[0].clone();
            another.name = name.to_string();
            workbook.sheets.push(another);
        }
        let module = parse_module(
            "Public Function Hidden() As String
               Hidden = Worksheets(\"Sheet2\").Visible & \"|\"
               Worksheets(\"Sheet2\").Visible = False
               Hidden = Hidden & Worksheets(\"Sheet2\").Visible & \"|\"
               Worksheets(\"Sheet3\").Visible = xlSheetVeryHidden
               Hidden = Hidden & Worksheets(\"Sheet3\").Visible & \"|\"
               Worksheets(\"Sheet2\").Range(\"A1\").Value = 5
               Hidden = Hidden & Worksheets(\"Sheet2\").Range(\"A1\").Value & \"|\"
               Worksheets(\"Sheet2\").Visible = True
               Hidden = Hidden & Worksheets(\"Sheet2\").Visible
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Hidden", vec![], &mut host).unwrap()
        };
        assert_eq!(result, Value::String("-1|0|2|5|-1".to_string()));

        // The workbook has to show something.
        let mut alone = super::tests::workbook();
        let module = parse_module(
            "Public Sub HideAll()\n  Worksheets(\"Sheet1\").Visible = False\nEnd Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut alone, 0).unwrap();
        let error = execute_with_host(&module, "HideAll", vec![], &mut host)
            .expect_err("a workbook has to show something");
        assert_eq!(error.vba_number, Some(1004));
        assert_eq!(error.vba_source.as_deref(), Some("Microsoft Excel"));
        assert!(host.workbook.sheets[0].visibility.is_shown());
    }

    /// The names a workbook keeps: making them, asking for them, dropping one.
    ///
    /// Every answer was asked of Excel. `RefersTo` is read as a formula, so a
    /// string without a leading `=` is stored as TEXT — `"Sheet1!$A$2"` comes
    /// back as `="Sheet1!$A$2"` and names no cells. A Range hands over its own
    /// address written absolute. The collection is handed out in alphabetical
    /// order, and the case a name was made with is the case it keeps.
    #[test]
    fn vba_keeps_the_names_a_workbook_is_given() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Named() As String
               Range(\"A1\").Value = 100
               Names.Add \"Sales\", \"=Sheet1!$A$1:$A$5\"
               Names.Add Name:=\"Bare\", RefersTo:=\"Sheet1!$A$2\"
               Names.Add \"FromRange\", Range(\"A1:A2\")
               Range(\"A4:A5\").Name = \"Tail\"
               Named = Names(\"Sales\").RefersTo & \"|\" & Names(\"Bare\").RefersTo & \"|\" & _
                 Names(\"FromRange\").RefersTo & \"|\" & Names(\"Tail\").RefersTo & \"|\" & _
                 Names.Count & \"|\" & Names(1).Name & \"|\" & Names(\"sales\").Name & \"|\" & _
                 Range(\"Sales\").Address(False, False) & \"|\" & _
                 Range(\"A4:A5\").Name.Name & \"|\" & _
                 Names(\"Sales\").RefersToRange.Address(False, False)
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Named", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String(
                "=Sheet1!$A$1:$A$5|=\"Sheet1!$A$2\"|=Sheet1!$A$1:$A$2|=Sheet1!$A$4:$A$5|\
                 4|Bare|Sales|A1:A5|Tail|A1:A5"
                    .to_string()
            )
        );
    }

    /// A name can be dropped, and writing one again writes over it.
    #[test]
    fn vba_writes_over_a_name_and_drops_one() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Rework() As String
               Names.Add \"Sales\", \"=Sheet1!$A$1:$A$5\"
               Names.Add \"Spare\", \"=Sheet1!$B$1\"
               Names.Add \"Sales\", \"=Sheet1!$A$1\"
               Names(\"Spare\").Delete
               Rework = Names(\"Sales\").RefersTo & \"|\" & Names.Count
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Rework", vec![], &mut host).unwrap()
        };

        assert_eq!(result, Value::String("=Sheet1!$A$1|1".to_string()));
    }

    /// What Excel refuses to call a name.
    #[test]
    fn vba_refuses_a_name_excel_would_refuse() {
        for (called, why) in [
            ("1Bad", "starts with a letter"),
            ("Two Words", "cannot hold"),
            ("B7", "shaped like a cell reference"),
        ] {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Try()\n  Names.Add \"{called}\", \"=Sheet1!$A$1\"\nEnd Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            let error = execute_with_host(&module, "Try", vec![], &mut host)
                .expect_err("Excel refuses this name")
                .to_string();
            assert!(
                error.contains(why),
                "{called} said {error:?}, which does not mention {why:?}"
            );
        }
        // And one Excel allows.
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Fine() As String
               Names.Add \"_Fine\", \"=Sheet1!$A$1\"
               Fine = Names(\"_Fine\").Name
             End Function\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        let result = execute_with_host(&module, "Fine", vec![], &mut host).unwrap();
        assert_eq!(result, Value::String("_Fine".to_string()));
    }

    /// What a name cannot be asked for, and what it says instead. A bare
    /// `Range` reaches every name in the workbook -- measured, it finds a
    /// name on another sheet -- so it is the worksheet's own `Range` that
    /// keeps to the sheet's names.
    #[test]
    fn vba_says_why_a_name_is_not_a_range() {
        for (call, expected) in [
            ("ActiveSheet.Range(\"Away\")", "answers only for its own names"),
            // A name of several blocks is now that many-block range, as in
            // Excel (r231), so "Scattered" is no longer refused.
            ("Range(\"Number\")", "which worksheet it means"),
            ("Range(\"WholeColumn\")", "not a block of cells"),
            ("Range(\"NoSuchName\")", "no name \"NoSuchName\""),
        ] {
            let mut workbook = named_workbook();
            let module = parse_module(&format!(
                "Public Sub Ask()\n  {call}.Select\nEnd Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            let error = execute_with_host(&module, "Ask", vec![], &mut host)
                .expect_err("the name is not a range")
                .to_string();
            assert!(
                error.contains(expected),
                "{call} said {error:?}, which does not mention {expected:?}"
            );
        }
    }

    /// A cut onto another sheet carries the sheet name with it.
    ///
    /// Asked of Excel, cutting `Sheet1!A2:B3` onto `Sheet2!D2`: the watcher
    /// left on Sheet1 reads `=Sheet2!D2`, a third sheet's `=Sheet1!A2` reads
    /// `=Sheet2!D2`, a watcher of the cell the block landed on reads `#REF!`,
    /// and of the formulas that travelled the one naming a cell that came
    /// along reads `=D2*10` while the one naming a neighbour left behind reads
    /// `=Sheet1!G9`.
    #[test]
    fn vba_cut_onto_another_sheet_says_which_sheet_it_means() {
        let mut workbook = workbook();
        for name in ["Sheet2", "Sheet3"] {
            let mut another = workbook.sheets[0].clone();
            another.name = name.to_string();
            workbook.sheets.push(another);
        }
        let module = parse_module(
            "Public Function Across() As String
               Worksheets(\"Sheet1\").Range(\"A2\").Value = 42
               Worksheets(\"Sheet1\").Range(\"G9\").Value = 7
               Worksheets(\"Sheet1\").Range(\"B2\").Formula = \"=A2*10\"
               Worksheets(\"Sheet1\").Range(\"B3\").Formula = \"=G9\"
               Worksheets(\"Sheet1\").Range(\"F1\").Formula = \"=A2\"
               Worksheets(\"Sheet1\").Range(\"F2\").Formula = \"=SUM(A2:B3)\"
               Worksheets(\"Sheet3\").Range(\"C1\").Formula = \"=Sheet1!A2\"
               Worksheets(\"Sheet2\").Range(\"H2\").Formula = \"=D2\"
               Worksheets(\"Sheet1\").Range(\"A2:B3\").Cut Worksheets(\"Sheet2\").Range(\"D2\")
               Across = Worksheets(\"Sheet2\").Range(\"E2\").Formula & \"|\" & _
                 Worksheets(\"Sheet2\").Range(\"E3\").Formula & \"|\" & _
                 Worksheets(\"Sheet1\").Range(\"F1\").Formula & \"|\" & _
                 Worksheets(\"Sheet1\").Range(\"F2\").Formula & \"|\" & _
                 Worksheets(\"Sheet3\").Range(\"C1\").Formula & \"|\" & _
                 Worksheets(\"Sheet2\").Range(\"H2\").Formula & \"|\" & _
                 Worksheets(\"Sheet2\").Range(\"D2\").Value
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Across", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String(
                "=D2*10|=Sheet1!G9|=Sheet2!D2|=SUM(Sheet2!D2:E3)|=Sheet2!D2|=#REF!|42".to_string()
            )
        );
    }

    /// Asked of Excel from VBA itself: the bar answers `False` until a macro
    /// writes to it, holds whatever string it is given, and is handed back by
    /// an empty string, `Empty` or `Null` — but NOT by `False`, which writes
    /// the word FALSE across it.
    #[test]
    fn vba_writes_across_the_status_bar_and_hands_it_back() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Report()
               Debug.Print Application.StatusBar
               Application.StatusBar = \"Working\"
               Debug.Print Application.StatusBar
               Application.StatusBar = \"\"
               Debug.Print Application.StatusBar
               Application.StatusBar = \"Working\"
               Application.StatusBar = Empty
               Debug.Print Application.StatusBar
               Application.StatusBar = \"Working\"
               Application.StatusBar = Null
               Debug.Print Application.StatusBar
             End Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        execute_with_host(&module, "Report", vec![], &mut host).unwrap();

        assert_eq!(host.status_bar, None);
        assert_eq!(
            host.take_debug_output(),
            vec![
                "False".to_string(),
                "Working".to_string(),
                "False".to_string(),
                "False".to_string(),
                "False".to_string(),
            ]
        );
    }

    /// The trap every guide walks into. `Application.StatusBar = False` is the
    /// documented way to restore the default bar, and Excel 16 does not
    /// restore it — it shows the word FALSE, and leaves it showing.
    #[test]
    fn vba_status_bar_false_writes_the_word_rather_than_giving_the_bar_back() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Report()
               Application.StatusBar = \"Working\"
               Application.StatusBar = False
               Debug.Print Application.StatusBar
               Application.StatusBar = True
               Debug.Print Application.StatusBar
             End Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        execute_with_host(&module, "Report", vec![], &mut host).unwrap();

        assert_eq!(host.status_bar.as_deref(), Some("TRUE"));
        assert_eq!(
            host.take_debug_output(),
            vec!["FALSE".to_string(), "TRUE".to_string()]
        );
    }

    /// A number reaches the bar written the way Excel writes one as text:
    /// fifteen significant digits, plainly if that fits twenty characters and
    /// in exponent form when it does not.
    #[test]
    fn vba_status_bar_shows_a_number_the_way_excel_writes_one() {
        let measured = [
            ("0", "0"),
            ("42", "42"),
            ("-0.5", "-0.5"),
            ("3.5", "3.5"),
            ("100000", "100000"),
            ("1 / 3", "0.333333333333333"),
            ("2 / 3", "0.666666666666667"),
            ("0.1 + 0.2", "0.3"),
            ("1E+15", "1000000000000000"),
            ("1E+16", "10000000000000000"),
            ("0.0000001", "0.0000001"),
            // Twenty characters fit; the twenty-first sends it to an exponent.
            ("1E+19", "10000000000000000000"),
            ("1E+20", "1E+20"),
            ("1.5E+20", "1.5E+20"),
            ("1E-18", "0.000000000000000001"),
            ("1E-19", "1E-19"),
            ("-1.5E-20", "-1.5E-20"),
            ("1E+100", "1E+100"),
            ("1234567890123456", "1234567890123460"),
            ("1.23456789012345678E+20", "1.23456789012346E+20"),
            // The widest Double there is gives up a significant digit to fit.
            ("1.7976931348623157E+308", "1.7976931348623E+308"),
        ];
        for (number, shown) in measured {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Report()
  Application.StatusBar = {number}
End Sub
"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Report", vec![], &mut host).unwrap();
            assert_eq!(host.status_bar.as_deref(), Some(shown), "for {number}");
        }
    }

    /// `Range.Formula` asks the same question and gets the same answer, but it
    /// is allowed one character more than the bar — so `1E+20` writes out in
    /// full here and does not there. Measured at both entrances; the two
    /// differ ONLY in that width.
    #[test]
    fn vba_writes_a_number_into_a_formula_the_way_excel_does() {
        let measured = [
            ("0", "0"),
            ("42", "42"),
            ("-0.5", "-0.5"),
            ("123.456", "123.456"),
            ("100.5", "100.5"),
            ("1E-5", "0.00001"),
            ("1 / 3", "0.333333333333333"),
            ("2 / 3", "0.666666666666667"),
            ("0.1 + 0.2", "0.3"),
            ("0.000123456789012345678", "0.000123456789012346"),
            ("1234567890123456", "1234567890123460"),
            ("9.99999999999999E+19", "99999999999999900000"),
            // Twenty-one characters fit, where the bar stops at twenty.
            ("1E+19", "10000000000000000000"),
            ("1E+20", "100000000000000000000"),
            ("1.5E+20", "150000000000000000000"),
            ("-1.5E+20", "-150000000000000000000"),
            ("1E+21", "1E+21"),
            ("1E-18", "0.000000000000000001"),
            ("1E-19", "0.0000000000000000001"),
            ("1E-20", "1E-20"),
            ("-1.5E-20", "-1.5E-20"),
            ("1E+100", "1E+100"),
            ("1.7976931348623157E+308", "1.79769313486232E+308"),
        ];
        for (number, written) in measured {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()
                   Range(\"A1\").Value = {number}
                   Debug.Print Range(\"A1\").Formula
                 End Sub
"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            assert_eq!(
                host.take_debug_output(),
                vec![written.to_string()],
                "for {number}"
            );
        }
    }

    /// 255 characters fit and a 256th is refused, counted in characters rather
    /// than bytes — so 255 kana fit as well. What was already on the bar stays.
    #[test]
    fn vba_status_bar_holds_255_characters() {
        for filler in ['z', '\u{3042}'] {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Report()
                   Application.StatusBar = \"{}\"
                   Debug.Print Len(Application.StatusBar)
                   Application.StatusBar = \"{}\"
                 End Sub\n",
                filler.to_string().repeat(255),
                filler.to_string().repeat(256),
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Report", vec![], &mut host)
                .expect_err("a 256th character is refused");
            assert_eq!(
                host.status_bar.as_deref(),
                Some(filler.to_string().repeat(255).as_str())
            );
            assert_eq!(host.take_debug_output(), vec!["255".to_string()]);
        }
    }

